screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentStoreId = '';
  let currentPeriod = 30;
  let salesChart = null;
  let weatherChart = null;

  // 店舗選択の初期化
  function initStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
      if (storeTable.records.length > 0) {
        currentStoreId = storeTable.records[0].店舗ID;
        storeSelect.value = currentStoreId;
      }
    }
  }

  // KPI計算
  function calculateKPIs(salesData, predictionData, orderData) {
    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    // 売上実績
    const filteredSales = salesData.filter(s => {
      const saleDate = new Date(s.売上日);
      return saleDate >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId);
    });

    const totalSales = filteredSales.reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    // 予測精度（MAPE計算）
    const accuracyData = predictionData.filter(p => p.実績数量 && p.予測数量);
    let avgAccuracy = 0;
    if (accuracyData.length > 0) {
      const mape = accuracyData.reduce((sum, p) => {
        const error = Math.abs(p.実績数量 - p.予測数量) / p.実績数量;
        return sum + error;
      }, 0) / accuracyData.length;
      avgAccuracy = Math.max(0, (1 - mape) * 100);
    }

    // 発注件数
    const filteredOrders = orderData.filter(o => {
      const orderDate = new Date(o.発注日);
      return orderDate >= periodStart && (!currentStoreId || o.店舗ID === currentStoreId);
    });

    // アラート件数（在庫切れフラグのある売上データから推定）
    const alertCount = filteredSales.filter(s => s.在庫切れフラグ).length;

    // UI更新
    container.querySelector('#sales-amount').textContent = `¥${totalSales.toLocaleString()}`;
    container.querySelector('#prediction-accuracy').textContent = `${avgAccuracy.toFixed(1)}%`;
    container.querySelector('#order-count').textContent = `${filteredOrders.length}件`;
    container.querySelector('#alert-count').textContent = `${alertCount}件`;
  }

  // 売上トレンドグラフ
  function renderSalesTrend(salesData) {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');

    if (salesChart) {
      salesChart.destroy();
    }

    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const filteredSales = salesData.filter(s => {
      const saleDate = new Date(s.売上日);
      return saleDate >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId);
    });

    // 日別集計
    const dailySales = {};
    filteredSales.forEach(s => {
      const dateKey = s.売上日.slice(0, 10);
      dailySales[dateKey] = (dailySales[dateKey] || 0) + s.売上金額;
    });

    const labels = Object.keys(dailySales).sort();
    const data = labels.map(date => dailySales[date]);

    salesChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: data,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function renderProductRanking(salesData, productData) {
    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const filteredSales = salesData.filter(s => {
      const saleDate = new Date(s.売上日);
      return saleDate >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId);
    });

    const productSales = {};
    filteredSales.forEach(s => {
      productSales[s.商品ID] = (productSales[s.商品ID] || 0) + s.売上金額;
    });

    const ranking = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10);

    const rankingHtml = ranking.map(([productId, amount], index) => {
      const product = productData.find(p => p.商品ID === productId);
      const productName = product ? product.商品名 : '不明な商品';
      return `
        <div class="ranking-item">
          <span class="rank">${index + 1}</span>
          <span class="product-name">${productName}</span>
          <span class="amount">¥${amount.toLocaleString()}</span>
        </div>
      `;
    }).join('');

    container.querySelector('#product-ranking').innerHTML = rankingHtml || '<div class="ranking-item"><span class="product-name">データがありません</span></div>';
  }

  // 天候影響分析チャート
  function renderWeatherChart(salesData, weatherData) {
    const ctx = container.querySelector('#weather-chart').getContext('2d');

    if (weatherChart) {
      weatherChart.destroy();
    }

    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const dailySales = {};
    const dailyWeather = {};

    salesData.forEach(s => {
      const dateKey = s.売上日.slice(0, 10);
      if (new Date(dateKey) >= periodStart && (!currentStoreId || s.店舗ID === currentStoreId)) {
        dailySales[dateKey] = (dailySales[dateKey] || 0) + s.売上金額;
      }
    });

    weatherData.forEach(w => {
      const dateKey = w.観測日.slice(0, 10);
      if (new Date(dateKey) >= periodStart && (!currentStoreId || w.店舗ID === currentStoreId)) {
        dailyWeather[dateKey] = w.平均気温;
      }
    });

    const labels = Object.keys(dailySales).sort();
    const salesValues = labels.map(date => dailySales[date] || 0);
    const tempValues = labels.map(date => dailyWeather[date] || 0);

    weatherChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: '売上金額',
          data: salesValues,
          borderColor: '#4a90e2',
          backgroundColor: 'rgba(74, 144, 226, 0.1)',
          yAxisID: 'y'
        }, {
          label: '平均気温',
          data: tempValues,
          borderColor: '#ff6a00',
          backgroundColor: 'rgba(255, 106, 0, 0.1)',
          yAxisID: 'y1'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            type: 'linear',
            display: true,
            position: 'left',
          },
          y1: {
            type: 'linear',
            display: true,
            position: 'right',
            grid: {
              drawOnChartArea: false,
            },
          }
        }
      }
    });
  }

  // 発注状況更新
  function updateOrderStatus(orderData) {
    const now = new Date();
    const periodStart = new Date(now.getTime() - currentPeriod * 24 * 60 * 60 * 1000);

    const filteredOrders = orderData.filter(o => {
      const orderDate = new Date(o.発注日);
      return orderDate >= periodStart && (!currentStoreId || o.店舗ID === currentStoreId);
    });

    const pending = filteredOrders.filter(o => o.発注ステータス === '未発注').length;
    const ordered = filteredOrders.filter(o => o.発注ステータス === '発注済').length;
    const received = filteredOrders.filter(o => o.発注ステータス === '納品済').length;

    container.querySelector('#pending-orders').textContent = pending;
    container.querySelector('#ordered-items').textContent = ordered;
    container.querySelector('#received-items').textContent = received;
  }

  // イベント・季節要因表示
  function renderEventFactors(eventData, seasonData) {
    const now = new Date();
    const futureDate = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

    const upcomingEvents = eventData.filter(e => {
      const startDate = new Date(e.開始日時);
      return startDate >= now && startDate <= futureDate && (!currentStoreId || e.店舗ID === currentStoreId);
    }).slice(0, 5);

    const eventHtml = upcomingEvents.map(e => `
      <div class="event-item">
        <span class="event-type">${e.イベント名}</span>
        <span class="event-impact">${e.影響度}</span>
      </div>
    `).join('');

    container.querySelector('#event-factors').innerHTML = eventHtml || '<div class="event-item"><span class="event-type">予定されたイベントはありません</span></div>';
  }

  // 在庫アラート表示
  function renderInventoryAlerts(salesData, productData) {
    const alerts = salesData.filter(s => s.在庫切れフラグ && (!currentStoreId || s.店舗ID === currentStoreId))
      .slice(0, 10);

    const alertHtml = alerts.map(s => {
      const product = productData.find(p => p.商品ID === s.商品ID);
      const productName = product ? product.商品名 : '不明な商品';
      return `
        <div class="alert-item">
          <span class="alert-product">${productName}</span>
          <span class="alert-level warning">警告</span>
        </div>
      `;
    }).join('');

    container.querySelector('#inventory-alerts').innerHTML = alertHtml || '<div class="alert-item"><span class="alert-product">アラートはありません</span></div>';
  }

  // データ更新
  async function updateDashboard() {
    try {
      const [salesData, productData, predictionData, orderData, weatherData, eventData, seasonData] = await Promise.all([
        window.aivicApi.list(3), // 売上実績データ
        window.aivicApi.list(2), // 商品マスタ
        window.aivicApi.list(8), // 需要予測結果
        window.aivicApi.list(9), // 発注データ
        window.aivicApi.list(4), // 天候データ
        window.aivicApi.list(5), // イベントデータ
        window.aivicApi.list(6)  // 季節情報データ
      ]);

      if (salesData && productData && predictionData && orderData) {
        calculateKPIs(salesData, predictionData, orderData);
        renderSalesTrend(salesData);
        renderProductRanking(salesData, productData);
        updateOrderStatus(orderData);
        renderInventoryAlerts(salesData, productData);

        if (weatherData) {
          renderWeatherChart(salesData, weatherData);
        }

        if (eventData && seasonData) {
          renderEventFactors(eventData, seasonData);
        }
      }
    } catch (error) {
      console.error('ダッシュボードデータの更新に失敗しました:', error);
      container.insertAdjacentHTML('afterbegin', '<div class="error-message">データの取得に失敗しました。ページを再読み込みしてください。</div>');
    }
  }

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateDashboard();
  });

  container.querySelector('#period-select').addEventListener('change', (e) => {
    currentPeriod = parseInt(e.target.value);
    updateDashboard();
  });

  // 初期化
  initStoreSelect();
  updateDashboard();
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let predictions = [];
  let inventory = [];

  // DOM要素の取得
  const storeSelect = container.querySelector('#store-select');
  const categorySelect = container.querySelector('#category-select');
  const dateStart = container.querySelector('#date-start');
  const dateEnd = container.querySelector('#date-end');
  const productSearch = container.querySelector('#product-search');
  const productTbody = container.querySelector('#product-tbody');
  const predictionArea = container.querySelector('#prediction-area');
  const orderModal = container.querySelector('#order-modal');
  const errorMessage = container.querySelector('#error-message');
  const successMessage = container.querySelector('#success-message');

  // メッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => errorMessage.classList.add('hidden'), 5000);
  }

  function showSuccess(message) {
    successMessage.textContent = message;
    successMessage.classList.remove('hidden');
    setTimeout(() => successMessage.classList.add('hidden'), 3000);
  }

  // バリデーション関数
  function validateDateRange() {
    const start = dateStart.value;
    const end = dateEnd.value;
    if (start && end && start > end) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }
    return true;
  }

  function validateOrderQuantity(quantity) {
    if (quantity === '' || quantity === null || quantity === undefined) {
      return { valid: false, message: '発注量を入力してください' };
    }
    if (isNaN(quantity) || !/^\d+$/.test(quantity.toString())) {
      return { valid: false, message: '発注量は数値で入力してください' };
    }
    const num = parseInt(quantity);
    if (num < 0) {
      return { valid: false, message: '発注量は正の数値を入力してください' };
    }
    if (num === 0) {
      return { valid: false, message: '発注量は1以上を入力してください' };
    }
    if (num > 999999999) {
      return { valid: false, message: '発注量が上限を超えています' };
    }
    return { valid: true };
  }

  // 商品一覧の再描画
  function renderProducts(products) {
    if (!products || products.length === 0) {
      productTbody.innerHTML = `
        <tr>
          <td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">
            ${storeSelect.value ? '該当する商品が見つかりませんでした' : '店舗を選択してください'}
          </td>
        </tr>
      `;
      return;
    }

    productTbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID) || {};
      const stock = Math.floor(Math.random() * 100) + 10; // 模擬在庫データ
      const predictedDemand = prediction.予測数量 || Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - stock + (product.最小発注数量 || 10));

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${stock}</td>
          <td style="text-align: right;">${predictedDemand}</td>
          <td style="text-align: right;">${recommendedOrder}</td>
          <td>
            <input type="number" class="input order-quantity" data-product-id="${product.商品ID}" 
                   style="width: 80px; text-align: right;" min="0" max="999999999" 
                   placeholder="${recommendedOrder}">
            <button class="action-btn secondary" style="margin-left: 4px; padding: 4px 8px; font-size: 12px;" 
                    onclick="this.previousElementSibling.value = ${recommendedOrder}">推奨採用</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-product-id="${product.商品ID}" 
                   style="width: 150px;" placeholder="発注理由を入力" maxlength="500">
          </td>
          <td>
            <button class="action-btn order-single-btn" data-product-id="${product.商品ID}" 
                    style="padding: 4px 12px; font-size: 12px;">発注</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 需要予測結果の表示
  function renderPredictionResults(storeId) {
    if (!storeId) {
      predictionArea.innerHTML = '<p style="color: var(--text-muted); margin: 0;">店舗を選択すると需要予測結果が表示されます</p>';
      return;
    }

    const storePredictions = predictions.filter(p => p.店舗ID === storeId);
    const totalPredicted = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const avgAccuracy = storePredictions.length > 0 
      ? Math.round(storePredictions.reduce((sum, p) => sum + (p.予測精度 || 85), 0) / storePredictions.length)
      : 85;

    predictionArea.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; text-align: left;">
        <div style="padding: 12px; background: var(--bg-card); border: 1px solid var(--border); border-radius: 4px;">
          <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">予測対象商品数</div>
          <div style="color: var(--text); font-size: 20px; font-weight: 600;">${storePredictions.length}品目</div>
        </div>
        <div style="padding: 12px; background: var(--bg-card); border: 1px solid var(--border); border-radius: 4px;">
          <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">総予測需要量</div>
          <div style="color: var(--text); font-size: 20px; font-weight: 600;">${totalPredicted}個</div>
        </div>
        <div style="padding: 12px; background: var(--bg-card); border: 1px solid var(--border); border-radius: 4px;">
          <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">平均予測精度</div>
          <div style="color: var(--text); font-size: 20px; font-weight: 600;">${avgAccuracy}%</div>
        </div>
        <div style="padding: 12px; background: var(--bg-card); border: 1px solid var(--border); border-radius: 4px;">
          <div style="color: var(--text-muted); font-size: 12px; margin-bottom: 4px;">最終更新</div>
          <div style="color: var(--text); font-size: 14px;">${new Date().toLocaleDateString()}</div>
        </div>
      </div>
    `;
  }

  // 検索・フィルター処理
  function filterProducts() {
    if (!validateDateRange()) return;

    let filtered = [...currentProducts];

    // カテゴリフィルター
    const selectedCategory = categorySelect.value;
    if (selectedCategory) {
      filtered = filtered.filter(p => p.商品カテゴリID === selectedCategory);
    }

    // 商品検索（部分一致）
    const searchTerm = productSearch.value.toLowerCase();
    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    renderProducts(filtered);
  }

  // 発注処理
  async function processOrder(productIds, quantities, reasons) {
    const orderDetails = [];

    for (let i = 0; i < productIds.length; i++) {
      const productId = productIds[i];
      const quantity = quantities[i];
      const reason = reasons[i];

      const validation = validateOrderQuantity(quantity);
      if (!validation.valid) {
        showError(`商品ID ${productId}: ${validation.message}`);
        return false;
      }

      const product = currentProducts.find(p => p.商品ID === productId);
      if (!product) continue;

      orderDetails.push({
        商品ID: productId,
        商品名: product.商品名,
        商品コード: product.商品コード,
        発注数量: parseInt(quantity),
        発注理由: reason || '',
        発注単価: product.単価 || 0,
        発注金額: parseInt(quantity) * (product.単価 || 0)
      });
    }

    if (orderDetails.length === 0) {
      showError('発注する商品がありません');
      return false;
    }

    // 発注確認モーダルを表示
    showOrderConfirmation(orderDetails);
    return true;
  }

  // 発注確認モーダル表示
  function showOrderConfirmation(orderDetails) {
    const detailsHtml = `
      <h4 style="color: var(--text); margin: 0 0 12px 0;">発注内容確認</h4>
      <div class="table-wrap" style="max-height: 300px; overflow-y: auto;">
        <table>
          <thead>
            <tr>
              <th style="color: var(--text);">商品コード</th>
              <th style="color: var(--text);">商品名</th>
              <th style="color: var(--text);">発注数量</th>
              <th style="color: var(--text);">単価</th>
              <th style="color: var(--text);">金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderDetails.map(detail => `
              <tr>
                <td>${detail.商品コード}</td>
                <td>${detail.商品名}</td>
                <td style="text-align: right;">${detail.発注数量}</td>
                <td style="text-align: right;">¥${detail.発注単価.toLocaleString()}</td>
                <td style="text-align: right;">¥${detail.発注金額.toLocaleString()}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <div style="margin-top: 12px; padding: 12px; background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px;">
        <strong style="color: var(--text);">合計金額: ¥${orderDetails.reduce((sum, d) => sum + d.発注金額, 0).toLocaleString()}</strong>
      </div>
    `;

    container.querySelector('#order-details').innerHTML = detailsHtml;
    orderModal.classList.remove('hidden');

    // 発注実行ボタンのイベント設定
    container.querySelector('#btn-confirm-order').onclick = async () => {
      await executeOrder(orderDetails);
    };
  }

  // 発注実行
  async function executeOrder(orderDetails) {
    try {
      const storeId = storeSelect.value;
      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      for (const detail of orderDetails) {
        const orderData = {
          店舗ID: storeId,
          商品ID: detail.商品ID,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: detail.発注数量,
          発注単価: detail.発注単価,
          発注金額: detail.発注金額,
          発注方法: '手動発注',
          発注ステータス: '発注済',
          発注理由: detail.発注理由,
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        const saved = await window.aivicApi.save(7, orderData); // 発注データテーブル
        if (!saved) {
          showError('発注処理に失敗しました');
          return;
        }
      }

      orderModal.classList.add('hidden');
      showSuccess(`${orderDetails.length}件の発注が完了しました`);

      // 発注量入力欄をクリア
      container.querySelectorAll('.order-quantity').forEach(input => input.value = '');
      container.querySelectorAll('.order-reason').forEach(input => input.value = '');
      container.querySelectorAll('.product-checkbox').forEach(cb => cb.checked = false);

    } catch (error) {
      showError('発注処理中にエラーが発生しました');
    }
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const allProducts = await window.aivicApi.list(2); // 商品マスタ
      if (!allProducts) {
        showError('データの取得に失敗しました');
        return;
      }

      const headers = ['商品コード', '商品名', '商品カテゴリID', '単価', '販売価格', '発注単位', '最小発注数量', 'リードタイム日数'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...allProducts.map(product => [
          product.商品コード || '',
          `"${(product.商品名 || '').replace(/"/g, '""')}"`,
          product.商品カテゴリID || '',
          product.単価 || 0,
          product.販売価格 || 0,
          product.発注単位 || 1,
          product.最小発注数量 || 1,
          product.リードタイム日数 || 7
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `商品一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      showError('CSVエクスポートに失敗しました');
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ読み込み
      stores = await window.aivicApi.list(1) || [];
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(s => s.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
        ).join('');

      // 商品マスタ読み込み
      const allProducts = await window.aivicApi.list(2) || [];

      // カテゴリ一覧作成（重複除去）
      const categoryIds = [...new Set(allProducts.map(p => p.商品カテゴリID).filter(Boolean))];
      categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
        categoryIds.map(catId => `<option value="${catId}">カテゴリ${catId}</option>`).join('');

      // 需要予測結果読み込み
      predictions = await window.aivicApi.list(5) || [];

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // イベントリスナー設定

  // 店舗選択変更
  storeSelect.addEventListener('change', async () => {
    const storeId = storeSelect.value;
    if (!storeId) {
      currentProducts = [];
      renderProducts([]);
      renderPredictionResults(null);
      return;
    }

    try {
      // 選択店舗の商品を取得（実際のシステムでは店舗別商品マスタがあると想定）
      const allProducts = await window.aivicApi.list(2) || [];
      currentProducts = allProducts.filter(p => p.有効フラグ);

      renderProducts(currentProducts);
      renderPredictionResults(storeId);

    } catch (error) {
      showError('商品データの取得に失敗しました');
    }
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', filterProducts);

  // リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', () => {
    categorySelect.value = '';
    dateStart.value = '';
    dateEnd.value = '';
    productSearch.value = '';
    renderProducts(currentProducts);
  });

  // 日付範囲バリデーション
  dateStart.addEventListener('change', validateDateRange);
  dateEnd.addEventListener('change', validateDateRange);

  // 商品検索（リアルタイム）
  productSearch.addEventListener('input', filterProducts);

  // カテゴリ選択変更
  categorySelect.addEventListener('change', filterProducts);

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 一括発注ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    const productIds = [];
    const quantities = [];
    const reasons = [];

    for (const checkbox of checkedBoxes) {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`.order-reason[data-product-id="${productId}"]`);

      productIds.push(productId);
      quantities.push(quantityInput.value);
      reasons.push(reasonInput.value);
    }

    processOrder(productIds, quantities, reasons);
  });

  // モーダル関連
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    orderModal.classList.add('hidden');
  });

  // イベントデリゲーション（個別発注ボタン）
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-single-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const reasonInput = container.querySelector(`.order-reason[data-product-id="${productId}"]`);

      await processOrder([productId], [quantityInput.value], [reasonInput.value]);
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistoryData = [];
  let filteredData = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#select-user");
        userSelect.innerHTML = '<option value="">すべてのユーザー</option>';
        users.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const userName = getUserName(row.ユーザーID);
      const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';
      const resultClass = row.処理結果 === '成功' ? 'success' : row.処理結果 === '失敗' ? 'error' : '';

      return `
        <tr data-id="${row.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${row.操作種別 || ''}</td>
          <td>${row.操作画面 || ''}</td>
          <td>${row.IPアドレス || ''}</td>
          <td><span style="color: ${resultClass === 'success' ? '#28a745' : resultClass === 'error' ? '#dc3545' : 'var(--text)'};">${row.処理結果 || ''}</span></td>
          <td>${row.処理時間 || ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ユーザー名を取得
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : userId || '';
  }

  // ページネーション処理
  function renderPagination() {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = filteredData.slice(startIndex, endIndex);

    renderRows(pageData);

    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${Math.max(totalPages, 1)}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // 検索フィルター処理
  function applyFilters() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const userId = container.querySelector("#select-user").value;
    const operationType = container.querySelector("#select-operation-type").value;
    const screenName = container.querySelector("#input-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#input-ip-address").value;
    const result = container.querySelector("#select-result").value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIpAddress(ipAddress)) {
      alert('正しいIPアドレス形式で入力してください');
      return;
    }

    filteredData = allHistoryData.filter(row => {
      // 日付範囲フィルター
      if (startDate && row.操作日時 && new Date(row.操作日時) < new Date(startDate)) return false;
      if (endDate && row.操作日時 && new Date(row.操作日時) > new Date(endDate)) return false;

      // ユーザーフィルター
      if (userId && row.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && row.操作種別 !== operationType) return false;

      // 画面名・機能名検索
      if (screenName && !(row.操作画面 || '').toLowerCase().includes(screenName)) return false;

      // IPアドレス検索
      if (ipAddress && !(row.IPアドレス || '').includes(ipAddress)) return false;

      // 処理結果フィルター
      if (result && row.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderPagination();
  }

  // IPアドレスバリデーション
  function isValidIpAddress(ip) {
    // IPv4の正規表現
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    // IPv6の簡易正規表現
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistoryData.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector("#detail-modal");
    const content = container.querySelector("#detail-content");

    const userName = getUserName(history.ユーザーID);
    const operationDate = history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : '';

    content.innerHTML = `
      <div style="display: grid; grid-template-columns: 150px 1fr; gap: 12px; line-height: 1.6;">
        <div style="font-weight: bold; color: var(--text);">操作日時:</div>
        <div style="color: var(--text);">${operationDate}</div>

        <div style="font-weight: bold; color: var(--text);">ユーザー名:</div>
        <div style="color: var(--text);">${userName}</div>

        <div style="font-weight: bold; color: var(--text);">操作種別:</div>
        <div style="color: var(--text);">${history.操作種別 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作画面:</div>
        <div style="color: var(--text);">${history.操作画面 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作対象テーブル:</div>
        <div style="color: var(--text);">${history.操作対象テーブル || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作対象ID:</div>
        <div style="color: var(--text);">${history.操作対象ID || ''}</div>

        <div style="font-weight: bold; color: var(--text);">操作内容:</div>
        <div style="color: var(--text); word-break: break-all;">${history.操作内容 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">IPアドレス:</div>
        <div style="color: var(--text);">${history.IPアドレス || ''}</div>

        <div style="font-weight: bold; color: var(--text);">ユーザーエージェント:</div>
        <div style="color: var(--text); word-break: break-all;">${history.ユーザーエージェント || ''}</div>

        <div style="font-weight: bold; color: var(--text);">処理結果:</div>
        <div style="color: var(--text);">${history.処理結果 || ''}</div>

        <div style="font-weight: bold; color: var(--text);">エラーメッセージ:</div>
        <div style="color: var(--text);">${history.エラーメッセージ || ''}</div>

        <div style="font-weight: bold; color: var(--text);">処理時間:</div>
        <div style="color: var(--text);">${history.処理時間 || ''}ms</div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // CSV出力
  function exportToCSV() {
    if (filteredData.length === 0) {
      alert('出力可能なデータがありません');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...filteredData.map(row => {
        const userName = getUserName(row.ユーザーID);
        const operationDate = row.操作日時 ? new Date(row.操作日時).toLocaleString('ja-JP') : '';

        return [
          `"${operationDate}"`,
          `"${userName}"`,
          `"${row.操作種別 || ''}"`,
          `"${row.操作画面 || ''}"`,
          `"${row.操作対象テーブル || ''}"`,
          `"${row.操作対象ID || ''}"`,
          `"${(row.操作内容 || '').replace(/"/g, '""')}"`,
          `"${row.IPアドレス || ''}"`,
          `"${(row.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${row.処理結果 || ''}"`,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${row.処理時間 || ''}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadUsers();

    try {
      const rows = await window.aivicApi.list(13); // システム操作履歴テーブル
      if (rows) {
        allHistoryData = rows.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredData = [...allHistoryData];
        renderPagination();
      } else {
        // API未接続時は初期データを使用
        allHistoryData = tables[13]?.records || [];
        filteredData = [...allHistoryData];
        renderPagination();
      }
    } catch (error) {
      console.error('操作履歴データの取得に失敗しました:', error);
      allHistoryData = tables[13]?.records || [];
      filteredData = [...allHistoryData];
      renderPagination();
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-start-date").value = '';
    container.querySelector("#input-end-date").value = '';
    container.querySelector("#select-user").value = '';
    container.querySelector("#select-operation-type").value = '';
    container.querySelector("#input-screen-name").value = '';
    container.querySelector("#input-ip-address").value = '';
    container.querySelector("#select-result").value = '';

    filteredData = [...allHistoryData];
    currentPage = 1;
    renderPagination();
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportToCSV);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderPagination();
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredData.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderPagination();
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add('hidden');
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // 初期化処理
  initializeScreen();

  async function initializeScreen() {
    // 店舗データを読み込んでドロップダウンに設定
    await loadStores();

    // 商品カテゴリを読み込んでチェックボックスを生成
    await loadProductCategories();

    // 日付フィールドのデフォルト値を設定
    setDefaultDates();

    // 季節要因スライダーのイベントリスナー
    setupSeasonalFactorSlider();

    // ボタンのイベントリスナーを設定
    setupEventListeners();
  }

  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeSelect = container.querySelector('#store-select');

      if (stores && stores.length > 0) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  async function loadProductCategories() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const categoryContainer = container.querySelector('#category-checkboxes');

      if (products && products.length > 0) {
        // 商品カテゴリIDでグループ化
        const categories = [...new Set(products.map(p => p.商品カテゴリID))];

        categories.forEach((categoryId, index) => {
          const label = document.createElement('label');
          label.style.display = 'block';
          label.innerHTML = `
            <input type="checkbox" value="${categoryId}" style="margin-right: 8px;">
            カテゴリ ${index + 1}
          `;
          categoryContainer.appendChild(label);
        });
      }
    } catch (error) {
      console.error('商品カテゴリの読み込みに失敗しました:', error);
    }
  }

  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);

    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);

    const lastYear = new Date(today);
    lastYear.setFullYear(today.getFullYear() - 1);

    // 予測対象期間のデフォルト値（明日から1週間後）
    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];

    // 学習データ期間のデフォルト値（過去1年間）
    container.querySelector('#learning-start-date').value = lastYear.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  function setupSeasonalFactorSlider() {
    const slider = container.querySelector('#seasonal-factor');
    const valueDisplay = container.querySelector('#seasonal-value');

    slider.addEventListener('input', function() {
      valueDisplay.textContent = this.value;
    });
  }

  function setupEventListeners() {
    // 天候データ取込ボタン
    container.querySelector('#btn-import-weather').addEventListener('click', async function() {
      await importWeatherData();
    });

    // イベントデータ取込ボタン
    container.querySelector('#btn-import-event').addEventListener('click', async function() {
      await importEventData();
    });

    // AI予測実行ボタン
    container.querySelector('#btn-execute-prediction').addEventListener('click', async function() {
      await executePrediction();
    });
  }

  async function importWeatherData() {
    const statusDiv = container.querySelector('#weather-status');
    statusDiv.textContent = '天候データを取得中...';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 成功の場合
      if (Math.random() > 0.3) { // 70%の確率で成功
        statusDiv.textContent = '天候データの取込が完了しました';
        statusDiv.style.color = '#28a745';
      } else {
        throw new Error('天候APIへの接続に失敗しました');
      }
    } catch (error) {
      statusDiv.textContent = `天候データの取込に失敗しました: ${error.message}`;
      statusDiv.style.color = '#dc3545';
    }
  }

  async function importEventData() {
    const statusDiv = container.querySelector('#event-status');
    statusDiv.textContent = 'イベントデータを取得中...';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      // 成功の場合
      if (Math.random() > 0.2) { // 80%の確率で成功
        statusDiv.textContent = 'イベントデータの取込が完了しました';
        statusDiv.style.color = '#28a745';
      } else {
        throw new Error('イベントデータファイルの形式が正しくありません');
      }
    } catch (error) {
      statusDiv.textContent = `イベントデータの取込に失敗しました: ${error.message}`;
      statusDiv.style.color = '#dc3545';
    }
  }

  async function executePrediction() {
    // バリデーション
    const validationError = validateInputs();
    if (validationError) {
      showError(validationError);
      return;
    }

    // 進捗バーを表示
    showProgressBar();

    try {
      // 予測処理の実行（模擬）
      await runPredictionProcess();

      // 成功メッセージを表示
      showSuccess('AI需要予測処理が正常に完了しました。結果は需要予測管理画面で確認できます。');

      // 需要予測管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591838939');
      }, 2000);

    } catch (error) {
      showError(error.message);
    } finally {
      hideProgressBar();
    }
  }

  function validateInputs() {
    const predictionStartDate = container.querySelector('#prediction-start-date').value;
    const predictionEndDate = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const selectedCategories = container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked');
    const learningStartDate = container.querySelector('#learning-start-date').value;
    const learningEndDate = container.querySelector('#learning-end-date').value;
    const accuracyThreshold = container.querySelector('#accuracy-threshold').value;

    // 予測対象期間のチェック
    if (!predictionStartDate || !predictionEndDate) {
      return '予測対象期間を設定してください。';
    }

    const today = new Date();
    const startDate = new Date(predictionStartDate);
    const endDate = new Date(predictionEndDate);

    if (startDate <= today) {
      return '予測対象期間に過去の日付は選択できません。';
    }

    if (endDate <= startDate) {
      return '予測対象期間の終了日は開始日より後の日付を選択してください。';
    }

    // 店舗選択のチェック
    if (!storeId) {
      return '店舗を選択してください。';
    }

    // 予測モデル選択のチェック
    if (!selectedModel) {
      return '予測モデルを選択してください。';
    }

    // 商品カテゴリ選択のチェック
    if (selectedCategories.length === 0) {
      return '商品カテゴリを1つ以上選択してください。';
    }

    // 学習データ期間のチェック
    if (!learningStartDate || !learningEndDate) {
      return '学習データ期間を設定してください。';
    }

    // 予測精度閾値のチェック
    const threshold = parseInt(accuracyThreshold);
    if (isNaN(threshold) || threshold < 0 || threshold > 100) {
      return '予測精度閾値は0〜100の範囲で入力してください。';
    }

    return null; // バリデーション成功
  }

  async function runPredictionProcess() {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    // 段階的に進捗を更新
    const steps = [
      { progress: 10, message: 'データ収集中...' },
      { progress: 30, message: '外部要因データ取得中...' },
      { progress: 50, message: 'モデル学習中...' },
      { progress: 70, message: '需要予測計算中...' },
      { progress: 90, message: '結果検証中...' },
      { progress: 100, message: '処理完了' }
    ];

    for (const step of steps) {
      await new Promise(resolve => setTimeout(resolve, 800));

      progressBar.style.width = step.progress + '%';
      progressText.textContent = `${step.progress}% - ${step.message}`;

      // ランダムでエラーを発生させる（テスト用）
      if (step.progress === 50 && Math.random() < 0.1) {
        throw new Error('学習データが不足しています。学習データ期間を延長してください。');
      }
    }

    // 予測結果データを保存
    await savePredictionResults();
  }

  async function savePredictionResults() {
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = Array.from(container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked')).map(cb => cb.value);
    const predictionStartDate = container.querySelector('#prediction-start-date').value;
    const predictionEndDate = container.querySelector('#prediction-end-date').value;
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked').value;
    const accuracyThreshold = container.querySelector('#accuracy-threshold').value;

    // 模擬的な予測結果データを生成
    const products = await window.aivicApi.list(2); // 商品マスタ
    const targetProducts = products.filter(p => selectedCategories.includes(p.商品カテゴリID));

    for (const product of targetProducts.slice(0, 5)) { // 最初の5商品のみ
      const predictionResult = {
        店舗ID: storeId,
        商品ID: product.商品ID,
        予測対象日: predictionStartDate,
        予測数量: Math.floor(Math.random() * 100) + 10,
        予測精度: Math.floor(Math.random() * 30) + parseInt(accuracyThreshold),
        推奨発注数量: Math.floor(Math.random() * 80) + 5,
        予測モデルバージョン: `${selectedModel}-v1.0`,
        実績数量: null,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI自動予測による結果',
        作成者ID: 'system'
      };

      await window.aivicApi.save(9, predictionResult); // 需要予測結果テーブル
    }
  }

  function showProgressBar() {
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressContainer.classList.remove('hidden');
    progressBar.style.width = '0%';
    progressText.textContent = '0%';

    hideMessages();
  }

  function hideProgressBar() {
    const progressContainer = container.querySelector('#progress-container');
    progressContainer.classList.add('hidden');
  }

  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');

    const successDiv = container.querySelector('#success-message');
    successDiv.classList.add('hidden');
  }

  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');

    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  function hideMessages() {
    const errorDiv = container.querySelector('#error-message');
    const successDiv = container.querySelector('#success-message');
    errorDiv.classList.add('hidden');
    successDiv.classList.add('hidden');
  }
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let currentStoreId = '';
  let editingProductId = null;

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#select-store');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品データを読み込み
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        currentProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
        renderProductTable();
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // 商品テーブルを描画
  function renderProductTable() {
    const tbody = container.querySelector('#product-table-body');
    if (!currentProducts.length) {
      tbody.innerHTML = '<tr><td colspan="11" style="text-align: center; color: var(--text-muted);">商品データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = currentProducts.map(product => `
      <tr data-id="${product.商品ID}">
        <td style="color: var(--text);">${product.商品名 || ''}</td>
        <td><input type="number" class="input current-stock" value="0" min="0" style="width: 80px;"></td>
        <td><input type="number" class="input safety-stock" value="10" min="0" style="width: 80px;"></td>
        <td><input type="number" class="input lead-time" value="${product.リードタイム日数 || 7}" min="1" max="365" style="width: 80px;"></td>
        <td class="forecast-demand" style="color: var(--text);">-</td>
        <td><input type="number" class="input weather-impact" value="50" min="0" max="100" style="width: 80px;"></td>
        <td><input type="number" class="input season-factor" value="1.0" min="0" step="0.1" style="width: 80px;"></td>
        <td class="ai-recommended" style="color: var(--text); font-weight: bold;">-</td>
        <td><input type="number" class="input manual-adjust" value="0" min="0" style="width: 80px;"></td>
        <td class="final-order" style="color: var(--text); font-weight: bold;">-</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${product.商品ID}">詳細</button>
        </td>
      </tr>
    `).join('');

    // 入力フィールドの変更イベント
    tbody.querySelectorAll('input').forEach(input => {
      input.addEventListener('input', calculateOrderQuantity);
      input.addEventListener('blur', calculateOrderQuantity);
    });
  }

  // 発注量計算
  function calculateOrderQuantity() {
    const rows = container.querySelectorAll('#product-table-body tr[data-id]');

    rows.forEach(row => {
      const currentStock = parseInt(row.querySelector('.current-stock').value) || 0;
      const safetyStock = parseInt(row.querySelector('.safety-stock').value) || 0;
      const leadTime = parseInt(row.querySelector('.lead-time').value) || 7;
      const weatherImpact = parseInt(row.querySelector('.weather-impact').value) || 50;
      const seasonFactor = parseFloat(row.querySelector('.season-factor').value) || 1.0;
      const manualAdjust = parseInt(row.querySelector('.manual-adjust').value) || 0;

      // 基本需要予測（簡易計算）
      const baseDemand = Math.floor(Math.random() * 100) + 50; // 実際はAI予測値

      // 天候・季節影響を考慮した需要予測
      const weatherAdjusted = baseDemand * (weatherImpact / 100);
      const seasonAdjusted = weatherAdjusted * seasonFactor;
      const forecastDemand = Math.round(seasonAdjusted);

      // AI推奨発注量計算
      const leadTimeDemand = Math.round(forecastDemand * (leadTime / 7));
      const aiRecommended = Math.max(0, leadTimeDemand + safetyStock - currentStock);

      // 最終発注量（手動調整適用）
      const finalOrder = manualAdjust > 0 ? manualAdjust : aiRecommended;

      // 結果を表示
      row.querySelector('.forecast-demand').textContent = forecastDemand;
      row.querySelector('.ai-recommended').textContent = aiRecommended;
      row.querySelector('.final-order').textContent = finalOrder;
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }

    // 未来日のみの期間チェック
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (new Date(startDate) > today && new Date(endDate) > today) {
      showError('対象期間に過去または現在の日付を含めてください');
      return false;
    }

    return true;
  }

  // 入力値バリデーション
  function validateFieldInputs() {
    const inputs = container.querySelectorAll('#product-table-body input[type="number"]');
    let hasError = false;

    inputs.forEach(input => {
      const value = parseFloat(input.value);
      const min = parseFloat(input.getAttribute('min'));
      const max = parseFloat(input.getAttribute('max'));

      if (isNaN(value)) {
        showError('数値を入力してください');
        input.focus();
        hasError = true;
        return;
      }

      if (min !== null && value < min) {
        if (input.classList.contains('current-stock')) {
          showError('現在在庫数は0以上の値を入力してください');
        } else if (input.classList.contains('lead-time') && max && value > max) {
          showError('リードタイムは1日から365日の範囲で入力してください');
        } else if (input.classList.contains('weather-impact')) {
          showError('天候影響度は0%から100%の範囲で入力してください');
        } else if (input.classList.contains('season-factor') && value < 0) {
          showError('季節補正係数は0以上の値を入力してください');
        } else if (input.classList.contains('manual-adjust')) {
          showError('手動調整値は0以上の値を入力してください');
        }
        input.focus();
        hasError = true;
        return;
      }

      if (max !== null && value > max) {
        if (input.classList.contains('lead-time')) {
          showError('リードタイムは1日から365日の範囲で入力してください');
        } else if (input.classList.contains('weather-impact')) {
          showError('天候影響度は0%から100%の範囲で入力してください');
        }
        input.focus();
        hasError = true;
        return;
      }
    });

    return !hasError;
  }

  // CSVエクスポート
  function exportCSV() {
    const rows = container.querySelectorAll('#product-table-body tr[data-id]');
    if (!rows.length) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['商品名', '現在在庫数', '安全在庫', 'リードタイム', '需要予測', '天候影響度', '季節補正係数', 'AI推奨発注量', '手動調整', '最終発注量'];
    let csvContent = '\uFEFF' + headers.join(',') + '\n';

    rows.forEach(row => {
      const data = [
        `"${row.cells[0].textContent}"`,
        row.querySelector('.current-stock').value,
        row.querySelector('.safety-stock').value,
        row.querySelector('.lead-time').value,
        row.querySelector('.forecast-demand').textContent,
        row.querySelector('.weather-impact').value,
        row.querySelector('.season-factor').value,
        row.querySelector('.ai-recommended').textContent,
        row.querySelector('.manual-adjust').value,
        row.querySelector('.final-order').textContent
      ];
      csvContent += data.join(',') + '\n';
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 商品検索・絞り込み
  function filterProducts() {
    const searchTerm = container.querySelector('#input-product-search').value.toLowerCase();
    const category = container.querySelector('#select-category').value;

    let filtered = currentProducts;

    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    if (category) {
      // カテゴリでの絞り込み（実際の実装では商品カテゴリマスタとの結合が必要）
      filtered = filtered.filter(p => {
        // 簡易実装：商品名にカテゴリ名が含まれるかチェック
        return (p.商品名 || '').includes(category);
      });
    }

    const originalProducts = currentProducts;
    currentProducts = filtered;
    renderProductTable();
    currentProducts = originalProducts; // 元のデータを保持
  }

  // モーダル操作
  function openDetailModal(productId) {
    const product = currentProducts.find(p => p.商品ID === productId);
    const row = container.querySelector(`tr[data-id="${productId}"]`);

    if (!product || !row) return;

    editingProductId = productId;
    const modal = container.querySelector('#detail-modal');

    container.querySelector('#modal-product-name').value = product.商品名 || '';
    container.querySelector('#modal-current-stock').value = row.querySelector('.current-stock').value;
    container.querySelector('#modal-safety-stock').value = row.querySelector('.safety-stock').value;
    container.querySelector('#modal-lead-time').value = row.querySelector('.lead-time').value;
    container.querySelector('#modal-weather-impact').value = row.querySelector('.weather-impact').value;
    container.querySelector('#modal-season-factor').value = row.querySelector('.season-factor').value;
    container.querySelector('#modal-manual-adjust').value = row.querySelector('.manual-adjust').value;

    modal.classList.remove('hidden');
  }

  function closeDetailModal() {
    container.querySelector('#detail-modal').classList.add('hidden');
    editingProductId = null;
  }

  function saveModalChanges() {
    if (!editingProductId) return;

    const row = container.querySelector(`tr[data-id="${editingProductId}"]`);
    if (!row) return;

    // バリデーション
    const currentStock = parseInt(container.querySelector('#modal-current-stock').value);
    const safetyStock = parseInt(container.querySelector('#modal-safety-stock').value);
    const leadTime = parseInt(container.querySelector('#modal-lead-time').value);
    const weatherImpact = parseInt(container.querySelector('#modal-weather-impact').value);
    const seasonFactor = parseFloat(container.querySelector('#modal-season-factor').value);
    const manualAdjust = parseInt(container.querySelector('#modal-manual-adjust').value);

    if (currentStock < 0) {
      showError('現在在庫数は0以上の値を入力してください');
      return;
    }
    if (safetyStock < 0) {
      showError('安全在庫は0以上の値を入力してください');
      return;
    }
    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1日から365日の範囲で入力してください');
      return;
    }
    if (weatherImpact < 0 || weatherImpact > 100) {
      showError('天候影響度は0%から100%の範囲で入力してください');
      return;
    }
    if (seasonFactor < 0) {
      showError('季節補正係数は0以上の値を入力してください');
      return;
    }
    if (manualAdjust < 0) {
      showError('手動調整値は0以上の値を入力してください');
      return;
    }

    // 値を更新
    row.querySelector('.current-stock').value = currentStock;
    row.querySelector('.safety-stock').value = safetyStock;
    row.querySelector('.lead-time').value = leadTime;
    row.querySelector('.weather-impact').value = weatherImpact;
    row.querySelector('.season-factor').value = seasonFactor;
    row.querySelector('.manual-adjust').value = manualAdjust;

    closeDetailModal();
    calculateOrderQuantity();
  }

  // イベントリスナー設定
  container.querySelector('#btn-calculate').addEventListener('click', () => {
    if (!validateInputs()) return;
    if (!validateFieldInputs()) return;

    const rows = container.querySelectorAll('#product-table-body tr[data-id]');
    if (!rows.length) {
      showError('計算対象の商品がありません');
      return;
    }

    calculateOrderQuantity();
  });

  container.querySelector('#btn-forecast-update').addEventListener('click', () => {
    if (!validateInputs()) return;
    calculateOrderQuantity();
  });

  container.querySelector('#btn-product-search').addEventListener('click', filterProducts);

  container.querySelector('#btn-filter-apply').addEventListener('click', filterProducts);

  container.querySelector('#input-product-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      filterProducts();
    }
  });

  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  container.querySelector('#btn-create-order').addEventListener('click', () => {
    window.showScreen('scr-1778591907544');
  });

  // モーダル関連イベント
  container.querySelector('#btn-modal-cancel').addEventListener('click', closeDetailModal);
  container.querySelector('#btn-modal-save').addEventListener('click', saveModalChanges);

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      openDetailModal(detailBtn.dataset.id);
    }

    // モーダル背景クリックで閉じる
    if (e.target.id === 'detail-modal') {
      closeDetailModal();
    }
  });

  // 初期化
  loadStores();
  loadProducts();

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector('#input-start-date').value = weekAgo;
  container.querySelector('#input-end-date').value = today;
}

