          <td><button class="action-btn secondary show-prediction" data-id="${product.商品ID}">根拠表示</button></td>
          <td><button class="action-btn add-to-order" data-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join('');
  }

