  // 発注総額更新
  function updateTotalAmount() {
    const total = orderItems.reduce((sum, item) => sum + (item.発注数量 * item.単価), 0);
    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (new Date(orderDate) < new Date(today)) {
      alert('発注日に過去の日付は設定できません');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) < new Date(orderDate)) {
      alert('納期は発注日以降の日付を設定してください');
      return false;
    }

    if (orderItems.length === 0) {
      alert('商品を選択してください');
      return false;
    }

    return true;
  }

  // 商品検索
  container.querySelector('#btn-search-product').addEventListener('click', () => {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const category = container.querySelector('#category-select').value;

    let filtered = products;

    if (keyword) {
      filtered = filtered.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(keyword)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(keyword))
      );
    }

    if (category) {
      // カテゴリでフィルタ（実際の実装では商品カテゴリIDで判定）
      filtered = filtered.filter(p => p.商品カテゴリID === category);
    }

    if (filtered.length === 0) {
      container.querySelector('#product-list').innerHTML = '<tr><td colspan="8" style="text-align: center;">該当する商品が見つかりませんでした</td></tr>';
    } else {
      renderProductList(filtered);
    }
  });

  // 商品を発注リストに追加
  container.addEventListener('click', (e) => {
    const addBtn = e.target.closest('.add-to-order');
    if (addBtn) {
      const productId = addBtn.dataset.id;
      const product = products.find(p => p.商品ID === productId);
      const row = addBtn.closest('tr');
      const manualQty = parseInt(row.querySelector('.manual-qty').value);

      if (manualQty < 0) {
        alert('手動調整数量は0以上の値を入力してください');
        return;
      }

      if (manualQty === 0) {
        if (!confirm('発注数量が0です。この商品を追加しますか？')) {
          return;
        }
      }

      const existingIndex = orderItems.findIndex(item => item.商品ID === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = manualQty;
      } else {
        orderItems.push({
          商品ID: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          発注数量: manualQty,
          単価: product.単価
        });
      }

      renderOrderList();
    }

    // 発注リストから削除
    const removeBtn = e.target.closest('.remove-item');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      orderItems.splice(index, 1);
      renderOrderList();
    }

    // 予測根拠表示
    const predictionBtn = e.target.closest('.show-prediction');
    if (predictionBtn) {
      const productId = predictionBtn.dataset.id;
      const product = products.find(p => p.商品ID === productId);
      showPredictionDetails(product);
    }
  });

  // 予測根拠詳細表示
  function showPredictionDetails(product) {
    const modal = container.querySelector('#prediction-modal');
    const details = container.querySelector('#prediction-details');

    details.innerHTML = `
      <h4>${product.商品名}</h4>
      <div style="margin: 15px 0;">
        <h5>予測要因分析</h5>
        <ul>
          <li>過去3ヶ月の平均売上: 45個/日</li>
          <li>季節性係数: 1.2（春季需要増加）</li>
          <li>曜日別傾向: 金土日に需要増（+20%）</li>
          <li>天候影響: 晴天時需要増（+10%）</li>
          <li>在庫切れリスク: 低（安全在庫確保）</li>
        </ul>
      </div>
      <div style="margin: 15px 0;">
        <h5>予測精度</h5>
        <p>信頼度: 85%（過去30日間の予測精度実績）</p>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 在庫状況確認
  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    const modal = container.querySelector('#stock-modal');
    const tbody = container.querySelector('#stock-list');

    tbody.innerHTML = products.slice(0, 10).map(product => {
      const stock = Math.floor(Math.random() * 100) + 5;
      let status = '十分';
      if (stock < 20) status = '不足';
      if (stock < 10) status = '欠品';

      return `
        <tr>
          <td>${product.商品コード}</td>
          <td>${product.商品名}</td>
          <td>${stock}</td>
          <td style="color: ${status === '十分' ? 'var(--text)' : status === '不足' ? '#ff9800' : '#f44336'}">${status}</td>
          <td>${new Date().toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    modal.classList.remove('hidden');
  });

  // 過去実績参照
  container.querySelector('#btn-past-data').addEventListener('click', () => {
    const modal = container.querySelector('#past-data-modal');
    modal.classList.remove('hidden');
  });

  container.querySelector('#btn-get-past-data').addEventListener('click', () => {
    const period = parseInt(container.querySelector('#past-period').value);
    const tbody = container.querySelector('#past-data-list');

    const pastData = [];
    for (let i = 0; i < period; i++) {
      const date = new Date();
      date.setMonth(date.getMonth() - i);
      pastData.push({
        yearMonth: `${date.getFullYear()}年${date.getMonth() + 1}月`,
        sales: Math.floor(Math.random() * 500) + 100,
        orders: Math.floor(Math.random() * 600) + 120,
        avgStock: Math.floor(Math.random() * 200) + 50
      });
    }

    tbody.innerHTML = pastData.map(data => `
      <tr>
        <td>${data.yearMonth}</td>
        <td>${data.sales}</td>
        <td>${data.orders}</td>
        <td>${data.avgStock}</td>
      </tr>
    `).join('');
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-stock-modal').addEventListener('click', () => {
    container.querySelector('#stock-modal').classList.add('hidden');
  });

  container.querySelector('#btn-close-past-modal').addEventListener('click', () => {
    container.querySelector('#past-data-modal').classList.add('hidden');
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを保存
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: orderDate,
          納期予定日: deliveryDate,
          発注数量: item.発注数量,
          発注単価: item.単価,
          発注金額: item.発注数量 * item.単価,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          自動発注フラグ: false,
          作成者ID: 'current-user-id'
        };

        await window.aivicApi.save(7, orderData); // 発注データテーブル
      }

      alert('発注書が正常に作成されました');
      window.showScreen('scr-1778591852463'); // 発注管理画面に遷移
    } catch (error) {
      alert('発注書の作成に失敗しました');
    }
  });

  // 手動調整数量の入力チェック
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('manual-qty')) {
      const value = parseInt(e.target.value);
      if (value < 0) {
        e.target.style.borderColor = '#f44336';
        e.target.title = '手動調整数量は0以上の値を入力してください';
      } else {
        e.target.style.borderColor = '';
        e.target.title = '';
      }
    }
  });

  // 初期データ読み込み
  loadStores();
  loadProducts();
}

function(container, apiUrl, tables) {
  let currentOrders = [];
  let selectedOrderIds = new Set();
  let stores = [];
  let products = [];

  const tbody = container.querySelector('#order-tbody');
  const storeSelect = container.querySelector('#store-select');
  const orderDateSpan = container.querySelector('#order-date');
  const selectAllCheckbox = container.querySelector('#select-all');
  const sendButton = container.querySelector('#btn-send-selected');
  const exportButton = container.querySelector('#btn-export-csv');
  const selectedCountSpan = container.querySelector('#selected-count');
  const messageArea = container.querySelector('#message-area');

  // テーブルインデックスを特定
  const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
  const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
  const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
  const demandTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [storesData, productsData, ordersData, demandsData] = await Promise.all([
        window.aivicApi.list(storeTableIndex),
        window.aivicApi.list(productTableIndex),
        window.aivicApi.list(orderTableIndex),
        window.aivicApi.list(demandTableIndex)
      ]);

      stores = storesData || tables[storeTableIndex]?.records || [];
      products = productsData || tables[productTableIndex]?.records || [];
      currentOrders = ordersData || tables[orderTableIndex]?.records || [];

      renderStoreOptions();
      updateOrderDate();
    } catch (error) {
      showMessage('データの読み込みに失敗しました', 'error');
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const activeStores = stores.filter(s => s.有効フラグ);
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      activeStores.map(store => 
        `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
      ).join('');
  }

  // 発注日付を更新
  function updateOrderDate() {
    const today = new Date();
    orderDateSpan.textContent = today.toLocaleDateString('ja-JP');
  }

  // 発注データを描画
  function renderOrders(orders) {
    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 40px;">
            発注データがありません
          </td>
        </tr>
      `;
      updateSendButton();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.商品ID === order.商品ID);
      const isSelected = selectedOrderIds.has(order.発注ID);
      const isSent = order.発注ステータス === '送信済み';

      return `
        <tr data-id="${order.発注ID}" ${isSent ? 'style="opacity: 0.6;"' : ''}>
          <td>
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.発注ID}"
                   ${isSelected ? 'checked' : ''}
                   ${isSent ? 'disabled' : ''} />
          </td>
          <td>${product?.商品コード || '-'}</td>
          <td>${product?.商品名 || '-'}</td>
          <td>${order.予測数量 || '-'}</td>
          <td>${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || '-'}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>
            <span class="status-badge ${getStatusClass(order.発注ステータス)}">
              ${order.発注ステータス || '未送信'}
            </span>
          </td>
        </tr>
      `;
    }).join('');

    updateSendButton();
    updateSelectedCount();
  }

  // ステータスのCSSクラスを取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済み': return 'status-sent';
      case '送信中': return 'status-sending';
      case '送信失敗': return 'status-failed';
      default: return 'status-pending';
    }
  }

  // 選択件数を更新
  function updateSelectedCount() {
    selectedCountSpan.textContent = `選択: ${selectedOrderIds.size}件`;
  }

  // 送信ボタンの状態を更新
  function updateSendButton() {
    sendButton.disabled = selectedOrderIds.size === 0;
  }

  // メッセージを表示
  function showMessage(text, type = 'info') {
    messageArea.className = `message-${type}`;
    messageArea.textContent = text;
    messageArea.classList.remove('hidden');

    setTimeout(() => {
      messageArea.classList.add('hidden');
    }, 5000);
  }

  // 店舗選択時の処理
  storeSelect.addEventListener('change', async (e) => {
    const storeId = e.target.value;
    selectedOrderIds.clear();
    selectAllCheckbox.checked = false;

    if (!storeId) {
      renderOrders([]);
      return;
    }

    try {
      const orders = await window.aivicApi.list(orderTableIndex);
      const storeOrders = orders.filter(order => order.店舗ID === storeId);
      currentOrders = storeOrders;
      renderOrders(storeOrders);
    } catch (error) {
      showMessage('発注データの取得に失敗しました', 'error');
    }
  });

  // 全選択チェックボックス
  selectAllCheckbox.addEventListener('change', (e) => {
    const isChecked = e.target.checked;
    const checkboxes = container.querySelectorAll('.order-checkbox:not(:disabled)');

    selectedOrderIds.clear();

    checkboxes.forEach(checkbox => {
      checkbox.checked = isChecked;
      if (isChecked) {
        selectedOrderIds.add(checkbox.dataset.id);
      }
    });

    updateSelectedCount();
    updateSendButton();
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;

      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not(:disabled)');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:not(:disabled):checked');
      selectAllCheckbox.checked = allCheckboxes.length > 0 && allCheckboxes.length === checkedCheckboxes.length;

      updateSelectedCount();
      updateSendButton();
    }
  });

  // 発注送信処理
  sendButton.addEventListener('click', async () => {
    if (selectedOrderIds.size === 0) {
      showMessage('発注対象が選択されていません', 'error');
      return;
    }

    // 発注金額上限チェック
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.発注ID));
    const totalAmount = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    const maxAmount = 10000000; // 1000万円上限

    if (totalAmount > maxAmount) {
      showMessage(`発注金額が上限値(¥${maxAmount.toLocaleString()})を超えています`, 'error');
      return;
    }

    if (!confirm(`${selectedOrderIds.size}件の発注を送信しますか？\n総額: ¥${totalAmount.toLocaleString()}`)) {
      return;
    }

    sendButton.disabled = true;
    sendButton.textContent = '送信中...';

    try {
      // 送信処理をシミュレート
      for (const orderId of selectedOrderIds) {
        const order = currentOrders.find(o => o.発注ID === orderId);
        if (order && order.発注ステータス !== '送信済み') {
          // 重複送信防止チェック
          if (order.発注ステータス === '送信済み') {
            showMessage('送信済みの発注データが含まれています', 'error');
            continue;
          }

          await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString(),
            更新者ID: 'current-user-id'
          });
        }
      }

      showMessage('発注データの送信が完了しました', 'success');
      selectedOrderIds.clear();
      selectAllCheckbox.checked = false;

      // データを再読み込み
      const orders = await window.aivicApi.list(orderTableIndex);
      const storeId = storeSelect.value;
      const storeOrders = orders.filter(order => order.店舗ID === storeId);
      currentOrders = storeOrders;
      renderOrders(storeOrders);

    } catch (error) {
      showMessage('通信エラーが発生しました。再送信してください。', 'error');
    } finally {
      sendButton.disabled = false;
      sendButton.textContent = '選択した発注を送信';
      updateSendButton();
    }
  });

  // CSVエクスポート
  exportButton.addEventListener('click', async () => {
    try {
      const orders = await window.aivicApi.list(orderTableIndex);
      const csvData = [
        ['発注ID', '店舗ID', '商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス', '発注日']
      ];

      orders.forEach(order => {
        const product = products.find(p => p.商品ID === order.商品ID);
        csvData.push([
          order.発注ID || '',
          order.店舗ID || '',
          product?.商品コード || '',
          product?.商品名 || '',
          order.予測数量 || '',
          order.発注数量 || '',
          order.仕入先名 || '',
          order.発注金額 || '',
          order.発注ステータス || '',
          order.発注日 || ''
        ]);
      });

      const csvContent = '\uFEFF' + csvData.map(row => 
        row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
      ).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      showMessage('CSVエクスポートに失敗しました', 'error');
    }
  });

  // 初期化
  loadInitialData();

  // スタイルを追加
  const style = document.createElement('style');
  style.textContent = `
    .form-row {
      margin-bottom: 15px;
    }
    .form-row label {
      display: block;
      margin-bottom: 5px;
      color: var(--text);
      font-weight: 500;
    }
    .action-bar {
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
      padding: 15px 0;
    }
    .status-badge {
      padding: 4px 8px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 500;
    }
    .status-sent {
      background: rgba(34, 197, 94, 0.1);
      color: #22c55e;
      border: 1px solid rgba(34, 197, 94, 0.3);
    }
    .status-sending {
      background: rgba(59, 130, 246, 0.1);
      color: #3b82f6;
      border: 1px solid rgba(59, 130, 246, 0.3);
    }
    .status-failed {
      background: rgba(239, 68, 68, 0.1);
      color: #ef4444;
      border: 1px solid rgba(239, 68, 68, 0.3);
    }
    .status-pending {
      background: rgba(156, 163, 175, 0.1);
      color: var(--text-muted);
      border: 1px solid rgba(156, 163, 175, 0.3);
    }
    .message-success {
      background: rgba(34, 197, 94, 0.1);
      color: #22c55e;
      border: 1px solid rgba(34, 197, 94, 0.3);
      border-radius: 4px;
      padding: 12px;
    }
    .message-error {
      background: rgba(239, 68, 68, 0.1);
      color: #ef4444;
      border: 1px solid rgba(239, 68, 68, 0.3);
      border-radius: 4px;
      padding: 12px;
    }
    .message-info {
      background: rgba(59, 130, 246, 0.1);
      color: #3b82f6;
      border: 1px solid rgba(59, 130, 246, 0.3);
      border-radius: 4px;
      padding: 12px;
    }
  `;
  document.head.appendChild(style);
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  let calculationResults = [];

  // 計算結果テーブル再描画関数
  function renderResults(results) {
    const tbody = container.querySelector("#result-tbody");
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted" style="text-align: center; padding: 40px;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id || ''}">
        <td>${result.productName || ''}</td>
        <td>${result.productCode || ''}</td>
        <td>${result.currentStock || 0}</td>
        <td>${result.forecastDemand || 0}</td>
        <td>${result.safetyStock || 0}</td>
        <td>${result.reorderPoint || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${result.recommendedOrder || 0}</td>
        <td>¥${(result.orderAmount || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id || ''}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.color = "#4caf50";
    errorDiv.style.borderColor = "#4caf50";
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
      errorDiv.style.color = "#ff6b6b";
      errorDiv.style.borderColor = "#ff6b6b";
    }, 3000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (stores) {
      const storeSelect = container.querySelector("#store-select");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.filter(store => store.有効フラグ).map(store => 
          `<option value="${store.店舗ID}">${store.店舗名}</option>`
        ).join('');
    }
  }

  // 需要予測結果表示更新
  async function updateForecastDisplay() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const forecastDiv = container.querySelector("#forecast-display");

    if (!storeId || !category) {
      forecastDiv.innerHTML = '<p class="muted">店舗と商品カテゴリを選択すると需要予測結果が表示されます</p>';
      return;
    }

    const forecasts = await window.aivicApi.list(FORECAST_TABLE);
    if (forecasts) {
      const relevantForecasts = forecasts.filter(f => f.店舗ID === storeId);
      if (relevantForecasts.length > 0) {
        const totalForecast = relevantForecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
        forecastDiv.innerHTML = `
          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
            <div>
              <div style="font-size: 0.9em; color: var(--text-muted);">予測対象商品数</div>
              <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">${relevantForecasts.length}件</div>
            </div>
            <div>
              <div style="font-size: 0.9em; color: var(--text-muted);">合計予測需要量</div>
              <div style="font-size: 1.2em; font-weight: bold; color: var(--primary);">${totalForecast.toLocaleString()}個</div>
            </div>
            <div>
              <div style="font-size: 0.9em; color: var(--text-muted);">平均予測精度</div>
              <div style="font-size: 1.2em; font-weight: bold; color: var(--text);">${Math.round(relevantForecasts.reduce((sum, f) => sum + (f.予測精度 || 85), 0) / relevantForecasts.length)}%</div>
            </div>
          </div>
        `;
      } else {
        forecastDiv.innerHTML = '<p class="muted">選択された条件の需要予測データがありません</p>';
      }
    }
  }

  // 発注量計算ロジック
  function calculateOrderQuantity(currentStock, forecastDemand, safetyStock, leadTime, orderCycle = 7) {
    const leadTimeDemand = Math.ceil(forecastDemand * (leadTime / 7)); // 週単位の需要を日単位に変換
    const cycleDemand = Math.ceil(forecastDemand * (orderCycle / 7));
    const reorderPoint = leadTimeDemand + safetyStock;

    if (currentStock <= reorderPoint) {
      return Math.max(0, cycleDemand + safetyStock - currentStock);
    }
    return 0;
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 1;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }
    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }
    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }
    if (isNaN(reorderPoint) || reorderPoint < 0) {
      showError("発注点は数値を入力してください");
      return false;
    }

    return true;
  }

  // 個別計算バリデーション
  function validateIndividualInputs() {
    const productCode = container.querySelector("#product-code").value.trim();
    const currentStock = parseInt(container.querySelector("#current-stock").value) || 0;
    const forecastDemand = parseInt(container.querySelector("#forecast-demand").value) || 0;
    const safetyStock = parseInt(container.querySelector("#individual-safety-stock").value) || 0;
    const orderCycle = parseInt(container.querySelector("#order-cycle").value) || 7;
    const leadTime = parseInt(container.querySelector("#individual-lead-time").value) || 1;

    if (!productCode) {
      showError("商品コードを入力してください");
      return false;
    }
    if (currentStock < 0) {
      showError("現在在庫数は0以上の値を入力してください");
      return false;
    }
    if (forecastDemand < 0) {
      showError("予測需要量は0以上の値を入力してください");
      return false;
    }
    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }
    if (orderCycle <= 0) {
      showError("発注サイクルは1以上の値を入力してください");
      return false;
    }
    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 初期データ読み込み
  loadStores();
  renderResults([]);

  // 店舗・カテゴリ選択時の需要予測表示更新
  container.querySelector("#store-select").addEventListener("change", updateForecastDisplay);
  container.querySelector("#category-select").addEventListener("change", updateForecastDisplay);

  // 計算実行ボタン
  container.querySelector("#btn-calculate").addEventListener("click", async () => {
    if (!validateInputs()) return;

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 1;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    try {
      // 商品データと需要予測データを取得
      const [products, forecasts] = await Promise.all([
        window.aivicApi.list(PRODUCTS_TABLE),
        window.aivicApi.list(FORECAST_TABLE)
      ]);

      if (!products || !forecasts) {
        showError("データの取得に失敗しました");
        return;
      }

      // カテゴリに該当する商品をフィルタ
      const categoryProducts = products.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category) && p.有効フラグ
      );

      if (categoryProducts.length === 0) {
        showError("選択されたカテゴリに該当する商品がありません");
        return;
      }

      // 計算結果生成
      calculationResults = categoryProducts.map(product => {
        const forecast = forecasts.find(f => f.商品ID === product.商品ID && f.店舗ID === storeId);
        const forecastDemand = forecast ? forecast.予測数量 : 0;
        const currentStock = Math.floor(Math.random() * 100); // 実際は在庫データから取得

        const recommendedOrder = calculateOrderQuantity(
          currentStock, 
          forecastDemand, 
          safetyStock, 
          leadTime
        );

        return {
          id: product.商品ID,
          productName: product.商品名,
          productCode: product.商品コード,
          currentStock,
          forecastDemand,
          safetyStock,
          reorderPoint: Math.ceil(forecastDemand * (leadTime / 7)) + safetyStock,
          recommendedOrder,
          orderAmount: recommendedOrder * (product.単価 || 0)
        };
      });

      renderResults(calculationResults);
      showSuccess(`${calculationResults.length}件の商品について発注量を計算しました`);

    } catch (error) {
      showError("計算処理中にエラーが発生しました");
    }
  });

  // 一括計算ボタン
  container.querySelector("#btn-bulk-calculate").addEventListener("click", async () => {
    if (!validateInputs()) return;

    const storeSelect = container.querySelector("#store-select");
    const selectedStores = Array.from(storeSelect.options)
      .filter(option => option.selected && option.value)
      .map(option => option.value);

    if (selectedStores.length === 0) {
      showError("計算対象の店舗を選択してください");
      return;
    }

    try {
      const [products, forecasts] = await Promise.all([
        window.aivicApi.list(PRODUCTS_TABLE),
        window.aivicApi.list(FORECAST_TABLE)
      ]);

      if (!products || !forecasts) {
        showError("データの取得に失敗しました");
        return;
      }

      const category = container.querySelector("#category-select").value;
      const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
      const leadTime = parseInt(container.querySelector("#lead-time").value) || 1;

      let allResults = [];

      selectedStores.forEach(storeId => {
        const categoryProducts = products.filter(p => 
          p.商品カテゴリID && p.商品カテゴリID.includes(category) && p.有効フラグ
        );

        const storeResults = categoryProducts.map(product => {
          const forecast = forecasts.find(f => f.商品ID === product.商品ID && f.店舗ID === storeId);
          const forecastDemand = forecast ? forecast.予測数量 : 0;
          const currentStock = Math.floor(Math.random() * 100);

          const recommendedOrder = calculateOrderQuantity(
            currentStock, 
            forecastDemand, 
            safetyStock, 
            leadTime
          );

          return {
            id: `${storeId}-${product.商品ID}`,
            productName: product.商品名,
            productCode: product.商品コード,
            currentStock,
            forecastDemand,
            safetyStock,
            reorderPoint: Math.ceil(forecastDemand * (leadTime / 7)) + safetyStock,
            recommendedOrder,
            orderAmount: recommendedOrder * (product.単価 || 0),
            storeId
          };
        });

        allResults = allResults.concat(storeResults);
      });

      calculationResults = allResults;
      renderResults(calculationResults);
      showSuccess(`${selectedStores.length}店舗、${allResults.length}件の商品について一括計算を完了しました`);

    } catch (error) {
      showError("一括計算処理中にエラーが発生しました");
    }
  });

  // 個別計算実行ボタン
  container.querySelector("#btn-individual-calculate").addEventListener("click", () => {
    if (!validateIndividualInputs()) return;

    const productCode = container.querySelector("#product-code").value.trim();
    const currentStock = parseInt(container.querySelector("#current-stock").value) || 0;
    const forecastDemand = parseInt(container.querySelector("#forecast-demand").value) || 0;
    const safetyStock = parseInt(container.querySelector("#individual-safety-stock").value) || 0;
    const orderCycle = parseInt(container.querySelector("#order-cycle").value) || 7;
    const leadTime = parseInt(container.querySelector("#individual-lead-time").value) || 1;

    const recommendedOrder = calculateOrderQuantity(
      currentStock, 
      forecastDemand, 
      safetyStock, 
      leadTime, 
      orderCycle
    );

    const result = {
      id: `individual-${Date.now()}`,
      productName: `商品-${productCode}`,
      productCode,
      currentStock,
      forecastDemand,
      safetyStock,
      reorderPoint: Math.ceil(forecastDemand * (leadTime / 7)) + safetyStock,
      recommendedOrder,
      orderAmount: recommendedOrder * 100 // 仮単価
    };

    calculationResults = [result];
    renderResults(calculationResults);
    showSuccess("個別計算が完了しました");
  });

  // 発注データ生成ボタン
  container.querySelector("#btn-generate-order").addEventListener("click", async () => {
    if (calculationResults.length === 0) {
      showError("発注データを生成する計算結果がありません");
      return;
    }

    if (!confirm("計算結果に基づいて発注データを生成しますか？")) return;

    try {
      let successCount = 0;

      for (const result of calculationResults) {
        if (result.recommendedOrder > 0) {
          const orderData = {
            店舗ID: result.storeId || container.querySelector("#store-select").value,
            商品ID: result.id,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
            発注数量: result.recommendedOrder,
            予測数量: result.forecastDemand,
            発注単価: Math.floor(result.orderAmount / result.recommendedOrder),
            発注金額: result.orderAmount,
            発注方法: 'AI自動発注',
            発注ステータス: '発注済',
            仕入先ID: 'supplier-001',
            発注理由: 'AI需要予測による自動発注',
            自動発注フラグ: true,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'system',
            更新者ID: 'system'
          };

          const saved = await window.aivicApi.save(ORDER_TABLE, orderData);
          if (saved) successCount++;
        }
      }

      showSuccess(`${successCount}件の発注データを生成しました`);

      // 発注管理画面に遷移
      setTimeout(() => {
        window.showScreen("scr-1778591852463");
      }, 2000);

    } catch (error) {
      showError("発注データ生成中にエラーが発生しました");
    }
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    if (calculationResults.length === 0) {
      showError("エクスポートする計算結果がありません");
      return;
    }

    const headers = ['商品名', '商品コード', '現在在庫数', '予測需要量', '安全在庫数', '発注点', '推奨発注量', '発注金額'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...calculationResults.map(result => [
        `"${result.productName || ''}"`,
        `"${result.productCode || ''}"`,
        result.currentStock || 0,
        result.forecastDemand || 0,
        result.safetyStock || 0,
        result.reorderPoint || 0,
        result.recommendedOrder || 0,
        result.orderAmount || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    showSuccess("CSVファイルをダウンロードしました");
  });

  // イベントデリゲーション（詳細ボタン）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      const result = calculationResults.find(r => r.id === resultId);
      if (result) {
        alert(`商品詳細\n商品名: ${result.productName}\n商品コード: ${result.productCode}\n推奨発注量: ${result.recommendedOrder}\n発注金額: ¥${result.orderAmount.toLocaleString()}`);
      }
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorDiv = container.querySelector("#error-message");
  const resultCountDiv = container.querySelector("#result-count");
  const storeSelect = container.querySelector("#select-store");
  const categorySelect = container.querySelector("#select-category");

  let allInventoryData = [];
  let storeData = [];
  let productData = [];

  // エラー表示関数
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 入力値検証
  function validateInput(value, type) {
    if (type === 'productName') {
      // XSS対策: HTMLタグやスクリプトを含む場合はエラー
      if (/<[^>]*>/.test(value) || /script/i.test(value)) {
        return "商品名に不正な文字が含まれています";
      }
    }
    if (type === 'productCode') {
      // 商品コード形式チェック（英数字とハイフンのみ、最大20文字）
      if (value && !/^[A-Za-z0-9\-]{1,20}$/.test(value)) {
        return "商品コードは英数字とハイフン、最大20文字で入力してください";
      }
    }
    return null;
  }

  // 在庫状況判定
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock <= 0) return "不足";
    if (currentStock < safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫データ再描画
  function renderInventoryRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する商品が見つかりませんでした</td></tr>';
      resultCountDiv.textContent = "検索結果: 0件";
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const product = productData.find(p => p.商品ID === row.商品ID) || {};
      const stockStatus = getStockStatus(row.現在在庫数 || 0, row.安全在庫数 || 0);
      const statusColor = stockStatus === "不足" ? "#ff4444" : stockStatus === "過剰" ? "#ff8800" : "#44aa44";

      return `
        <tr data-id="${row.在庫ID || row.id || ''}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${(row.現在在庫数 || 0).toLocaleString()}</td>
          <td style="text-align: right;">${(row.安全在庫数 || 0).toLocaleString()}</td>
          <td><span style="color: ${statusColor}; font-weight: bold;">${stockStatus}</span></td>
          <td style="text-align: right;">¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${row.更新日時 ? new Date(row.更新日時).toLocaleString() : ''}</td>
        </tr>
      `;
    }).join("");

    resultCountDiv.textContent = `検索結果: ${rows.length}件`;
  }

  // 店舗・カテゴリ選択肢を設定
  async function loadMasterData() {
    try {
      // 店舗マスタ取得
      const stores = await window.aivicApi.list(1);
      if (stores) {
        storeData = stores.filter(s => s.有効フラグ);
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          storeData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2);
      if (products) {
        productData = products.filter(p => p.有効フラグ);

        // カテゴリ一覧作成（重複除去）
        const categories = [...new Set(productData.map(p => p.商品カテゴリID).filter(Boolean))];
        categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
          categories.map(cat => `<option value="${cat}">カテゴリ${cat}</option>`).join("");
      }
    } catch (error) {
      console.error("マスタデータ取得エラー:", error);
    }
  }

  // 在庫データ検索・フィルタリング
  async function searchInventory() {
    hideError();

    const storeId = storeSelect.value;
    const categoryId = categorySelect.value;
    const productName = container.querySelector("#input-product-name").value.trim();
    const productCode = container.querySelector("#input-product-code").value.trim();
    const stockStatus = container.querySelector("#select-stock-status").value;

    // 店舗選択チェック
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 入力値検証
    const nameError = validateInput(productName, 'productName');
    if (nameError) {
      showError(nameError);
      return;
    }

    const codeError = validateInput(productCode, 'productCode');
    if (codeError) {
      showError(codeError);
      return;
    }

    try {
      // 在庫データを模擬生成（実際のシステムでは在庫テーブルから取得）
      let inventoryRows = productData.map(product => ({
        在庫ID: `inv_${product.商品ID}`,
        店舗ID: storeId,
        商品ID: product.商品ID,
        現在在庫数: Math.floor(Math.random() * 200) + 10,
        安全在庫数: Math.floor(Math.random() * 50) + 20,
        更新日時: new Date().toISOString()
      }));

      // フィルタリング
      if (categoryId) {
        const categoryProducts = productData.filter(p => p.商品カテゴリID === categoryId).map(p => p.商品ID);
        inventoryRows = inventoryRows.filter(row => categoryProducts.includes(row.商品ID));
      }

      if (productName) {
        const matchingProducts = productData.filter(p => 
          p.商品名 && p.商品名.toLowerCase().includes(productName.toLowerCase())
        ).map(p => p.商品ID);
        inventoryRows = inventoryRows.filter(row => matchingProducts.includes(row.商品ID));
      }

      if (productCode) {
        const matchingProducts = productData.filter(p => 
          p.商品コード && p.商品コード.toLowerCase().includes(productCode.toLowerCase())
        ).map(p => p.商品ID);
        inventoryRows = inventoryRows.filter(row => matchingProducts.includes(row.商品ID));
      }

      if (stockStatus) {
        inventoryRows = inventoryRows.filter(row => {
          const status = getStockStatus(row.現在在庫数, row.安全在庫数);
          return status === stockStatus;
        });
      }

      allInventoryData = inventoryRows;
      renderInventoryRows(inventoryRows);

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // 検索条件クリア
  function clearSearchConditions() {
    storeSelect.value = "";
    categorySelect.value = "";
    container.querySelector("#input-product-name").value = "";
    container.querySelector("#input-product-code").value = "";
    container.querySelector("#select-stock-status").value = "";
    hideError();
    tbody.innerHTML = "";
    resultCountDiv.textContent = "検索結果: 0件";
  }

  // CSVエクスポート
  function exportToCSV() {
    if (!allInventoryData || allInventoryData.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "単価", "最終更新日時"];
    const csvRows = [headers.join(",")];

    allInventoryData.forEach(row => {
      const product = productData.find(p => p.商品ID === row.商品ID) || {};
      const stockStatus = getStockStatus(row.現在在庫数 || 0, row.安全在庫数 || 0);
      const csvRow = [
        `"${product.商品コード || ''}"`,
        `"${product.商品名|| ''}"`,
        row.現在在庫数 || 0,
        row.安全在庫数 || 0,
        `"${stockStatus}"`,
        product.単価 || 0,
        `"${row.更新日時 ? new Date(row.更新日時).toLocaleString() : ''}"`
      ];
      csvRows.push(csvRow.join(","));
    });

    const csvContent = "\uFEFF" + csvRows.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", searchInventory);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // 初期化
  loadMasterData();
  renderInventoryRows([]);
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 9; // 需要予測結果
  const ORDERS_TABLE = 10; // 発注データ

  let currentForecastData = [];
  let currentStoreId = '';

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗選択肢を設定
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (!stores) return;

    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.filter(s => s.有効フラグ).forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // 発注金額計算
  function calculateOrderAmount(quantity, unitPrice) {
    return (parseInt(quantity) || 0) * (parseInt(unitPrice) || 0);
  }

  // 合計金額更新
  function updateTotalAmount() {
    let total = 0;
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      const row = input.closest('tr');
      const unitPrice = parseInt(row.querySelector('.unit-price').textContent) || 0;
      const quantity = parseInt(input.value) || 0;
      total += quantity * unitPrice;
    });
    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // 需要予測データ表示
  function renderForecastData(data) {
    const tbody = container.querySelector('#forecast-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(item => `
      <tr data-id="${item.予測結果ID}">
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td>${item.商品カテゴリ || ''}</td>
        <td style="text-align: right;">${(item.予測数量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(item.推奨発注数量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(item.現在在庫数量 || 0).toLocaleString()}</td>
        <td>
          <input type="number" class="input order-quantity-input" 
                 style="width: 80px; text-align: right;" 
                 min="0" max="999999" 
                 data-product-id="${item.商品ID}"
                 value="0">
        </td>
        <td class="unit-price" style="text-align: right;">${(item.発注単価 || 0).toLocaleString()}</td>
        <td class="order-amount" style="text-align: right;">0</td>
        <td>
          <button class="action-btn secondary recommend-btn" data-recommend="${item.推奨発注数量 || 0}">推奨採用</button>
        </td>
      </tr>
    `).join('');

    // 発注数量入力時の金額計算
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      input.addEventListener('input', function() {
        const row = this.closest('tr');
        const unitPrice = parseInt(row.querySelector('.unit-price').textContent) || 0;
        const quantity = parseInt(this.value) || 0;
        const amount = calculateOrderAmount(quantity, unitPrice);
        row.querySelector('.order-amount').textContent = amount.toLocaleString();
        updateTotalAmount();
      });

      input.addEventListener('blur', function() {
        // 数値バリデーション
        const value = this.value;
        if (value && (isNaN(value) || parseFloat(value) < 0)) {
          showError('発注数量は0以上の数値を入力してください');
          this.focus();
        }
      });
    });

    updateTotalAmount();
  }

  // 需要予測データ取得・表示
  async function loadForecastData() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const category = container.querySelector('#category-filter').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    // 過去日付チェック
    if (orderDate < today) {
      showError('発注日付には本日以降の日付を選択してください');
      return;
    }

    currentStoreId = storeId;

    // 需要予測データ取得
    const forecasts = await window.aivicApi.list(FORECAST_TABLE);
    const products = await window.aivicApi.list(PRODUCTS_TABLE);

    if (!forecasts || !products) {
      showError('データの取得に失敗しました');
      return;
    }

    // 店舗・日付でフィルタリング
    let filteredForecasts = forecasts.filter(f => 
      f.店舗ID === storeId && 
      f.予測対象日 && 
      f.予測対象日.split('T')[0] === orderDate
    );

    // カテゴリフィルタリング
    if (category) {
      const categoryProducts = products.filter(p => p.商品カテゴリID === category);
      const categoryProductIds = categoryProducts.map(p => p.商品ID);
      filteredForecasts = filteredForecasts.filter(f => categoryProductIds.includes(f.商品ID));
    }

    // 商品情報をマージ
    const enrichedData = filteredForecasts.map(forecast => {
      const product = products.find(p => p.商品ID === forecast.商品ID);
      return {
        ...forecast,
        商品コード: product?.商品コード || '',
        商品名: product?.商品名|| '',
        商品カテゴリ: product?.商品カテゴリID || '',
        発注単価: product?.単価 || 0,
        現在在庫数量: Math.floor(Math.random() * 100) // サンプル在庫数
      };
    });

    currentForecastData = enrichedData;
    renderForecastData(enrichedData);
  }

  // 推奨発注数量一括入力
  function bulkApplyRecommended() {
    if (confirm('全ての商品に推奨発注数量を適用しますか？')) {
      container.querySelectorAll('.order-quantity-input').forEach(input => {
        const row = input.closest('tr');
        const recommendBtn = row.querySelector('.recommend-btn');
        const recommendedQty = recommendBtn.dataset.recommend;
        input.value = recommendedQty;

        // 金額計算
        const unitPrice = parseInt(row.querySelector('.unit-price').textContent) || 0;
        const amount = calculateOrderAmount(recommendedQty, unitPrice);
        row.querySelector('.order-amount').textContent = amount.toLocaleString();
      });
      updateTotalAmount();
    }
  }

  // 発注確認・承認実行
  function executeOrder() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    if (orderDate < today) {
      showError('発注日付には本日以降の日付を選択してください');
      return;
    }

    // 発注データ収集
    const orderItems = [];
    let hasError = false;

    container.querySelectorAll('.order-quantity-input').forEach(input => {
      const quantity = input.value.trim();
      const row = input.closest('tr');
      const productId = input.dataset.productId;
      const unitPrice = parseInt(row.querySelector('.unit-price').textContent) || 0;

      if (quantity === '') {
        showError('発注数量を入力してください');
        hasError = true;
        return;
      }

      if (isNaN(quantity) || parseFloat(quantity) < 0) {
        showError('発注数量は0以上の数値を入力してください');
        hasError = true;
        return;
      }

      const qty = parseInt(quantity);
      if (qty > 0) {
        orderItems.push({
          商品ID: productId,
          商品コード: row.cells[0].textContent,
          商品名: row.cells[1].textContent,
          発注数量: qty,
          発注単価: unitPrice,
          発注金額: qty * unitPrice
        });
      }
    });

    if (hasError) return;

    if (orderItems.length === 0) {
      showError('発注数量が入力された商品がありません');
      return;
    }

    // 確認ダイアログ表示
    showOrderConfirmDialog(orderItems, storeId, orderDate);
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(orderItems, storeId, orderDate) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#confirm-content');

    const totalAmount = orderItems.reduce((sum, item) => sum + item.発注金額, 0);

    content.innerHTML = `
      <p><strong>発注日:</strong> ${orderDate}</p>
      <p><strong>店舗:</strong> ${container.querySelector('#store-select option:checked').textContent}</p>
      <p><strong>発注商品数:</strong> ${orderItems.length}件</p>
      <div class="table-wrap" style="margin: 1rem 0;">
        <table>
          <thead>
            <tr>
              <th>商品コード</th>
              <th>商品名</th>
              <th>発注数量</th>
              <th>単価</th>
              <th>金額</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => `
              <tr>
                <td>${item.商品コード}</td>
                <td>${item.商品名}</td>
                <td style="text-align: right;">${item.発注数量.toLocaleString()}</td>
                <td style="text-align: right;">${item.発注単価.toLocaleString()}円</td>
                <td style="text-align: right;">${item.発注金額.toLocaleString()}円</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
      <p style="text-align: right; font-size: 1.1rem; font-weight: bold;">
        <strong>合計金額: ${totalAmount.toLocaleString()}円</strong>
      </p>
    `;

    dialog.classList.remove('hidden');

    // 承認実行
    container.querySelector('#btn-confirm-ok').onclick = async () => {
      try {
        // 発注データ保存
        for (const item of orderItems) {
          const orderData = {
            店舗ID: storeId,
            商品ID: item.商品ID,
            発注日: orderDate + 'T00:00:00',
            納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
            発注数量: item.発注数量,
            発注単価: item.発注単価,
            発注金額: item.発注金額,
            発注方法: 'AI推奨採用',
            発注ステータス: '承認済み',
            仕入先ID: 'supplier-001',
            発注理由: 'AI需要予測に基づく発注',
            承認者ID: 'user-001',
            承認日時: new Date().toISOString(),
            自動発注フラグ: false,
            作成者ID: 'user-001',
            更新者ID: 'user-001'
          };

          await window.aivicApi.save(ORDERS_TABLE, orderData);
        }

        dialog.classList.add('hidden');
        alert('発注が正常に承認・実行されました');

        // 発注管理画面に遷移
        window.showScreen('scr-1778591852463');

      } catch (error) {
        showError('発注処理中にエラーが発生しました');
      }
    };

    // キャンセル
    container.querySelector('#btn-confirm-cancel').onclick = () => {
      dialog.classList.add('hidden');
    };
  }

  // イベントリスナー設定
  container.querySelector('#btn-display').addEventListener('click', loadForecastData);
  container.querySelector('#btn-bulk-recommend').addEventListener('click', bulkApplyRecommended);
  container.querySelector('#btn-update-forecast').addEventListener('click', loadForecastData);
  container.querySelector('#btn-execute-order').addEventListener('click', executeOrder);

  // 推奨採用ボタンのイベントデリゲーション
  container.addEventListener('click', (e) => {
    const recommendBtn = e.target.closest('.recommend-btn');
    if (recommendBtn) {
      const row = recommendBtn.closest('tr');
      const input = row.querySelector('.order-quantity-input');
      const recommendedQty = recommendBtn.dataset.recommend;
      input.value = recommendedQty;

      // 金額計算
      const unitPrice = parseInt(row.querySelector('.unit-price').textContent) || 0;
      const amount = calculateOrderAmount(recommendedQty, unitPrice);
      row.querySelector('.order-amount').textContent = amount.toLocaleString();
      updateTotalAmount();
    }
  });

  // 初期化
  loadStores();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let currentSort = { column: 'accuracy', direction: 'desc' };

  // 店舗データを店舗選択に追加
  function populateStoreFilter() {
    const storeSelect = container.querySelector('#filter-store');
    const stores = tables[1]?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // 精度ランキングテーブルの再描画
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-table-body');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((item, index) => `
      <tr data-id="${item.id}">
        <td>${index + 1}</td>
        <td>${item.storeName || ''}</td>
        <td>${item.category || ''}</td>
        <td style="color: ${item.accuracy >= 80 ? 'var(--primary)' : '#ff6a00'}; font-weight: 600;">${item.accuracy}%</td>
        <td>${item.mape}%</td>
        <td>${item.rmse}</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${item.accuracy >= 80 ? 'rgba(34, 197, 94, 0.1)' : 'rgba(255, 106, 0, 0.1)'}; color: ${item.accuracy >= 80 ? '#22c562' : '#ff6a00'};">
            ${item.accuracy >= 80 ? '正常' : 'アラート'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // 予測精度推移グラフの描画
  function drawAccuracyTrendChart() {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 40;

    // 背景をクリア
    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const data = [
      { date: '1月', accuracy: 82 },
      { date: '2月', accuracy: 85 },
      { date: '3月', accuracy: 78 },
      { date: '4月', accuracy: 88 },
      { date: '5月', accuracy: 85 },
      { date: '6月', accuracy: 90 }
    ];

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // データポイントとライン
    const stepX = (width - padding * 2) / (data.length - 1);
    const stepY = (height - padding * 2) / 100;

    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((point, index) => {
      const x = padding + index * stepX;
      const y = height - padding - point.accuracy * stepY;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(point.date, x, height - padding + 20);
      ctx.fillText(point.accuracy + '%', x, y - 10);
    });

    ctx.stroke();
  }

  // 予測vs実績比較チャートの描画
  function drawPredictionVsActualChart() {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 40;

    ctx.clearRect(0, 0, width, height);

    // サンプルデータ
    const data = [
      { date: '1日', predicted: 120, actual: 115 },
      { date: '2日', predicted: 135, actual: 142 },
      { date: '3日', predicted: 110, actual: 108 },
      { date: '4日', predicted: 145, actual: 138 },
      { date: '5日', predicted: 125, actual: 130 },
      { date: '6日', predicted: 155, actual: 160 }
    ];

    // 軸の描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    const stepX = (width - padding * 2) / (data.length - 1);
    const maxValue = Math.max(...data.map(d => Math.max(d.predicted, d.actual)));
    const stepY = (height - padding * 2) / maxValue;

    // 予測値ライン
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, index) => {
      const x = padding + index * stepX;
      const y = height - padding - point.predicted * stepY;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績値ライン
    ctx.strokeStyle = '#22c562';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, index) => {
      const x = padding + index * stepX;
      const y = height - padding - point.actual * stepY;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(width - 120, 20, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', width - 100, 25);

    ctx.fillStyle = '#22c562';
    ctx.fillRect(width - 120, 35, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', width - 100, 40);
  }

  // データの読み込みと表示
  async function loadData() {
    try {
      const predictionData = await window.aivicApi.list(4); // 需要予測結果
      if (predictionData) {
        // 精度データの生成（サンプル）
        currentData = [
          { id: '1', storeName: '店舗A', category: '食品', accuracy: 85.2, mape: 14.8, rmse: 12.3 },
          { id: '2', storeName: '店舗B', category: '飲料', accuracy: 78.5, mape: 21.5, rmse: 15.7 },
          { id: '3', storeName: '店舗C', category: '日用品', accuracy: 92.1, mape: 7.9, rmse: 8.2 },
          { id: '4', storeName: '店舗D', category: '食品', accuracy: 88.7, mape: 11.3, rmse: 10.1 },
          { id: '5', storeName: '店舗E', category: '飲料', accuracy: 75.3, mape: 24.7, rmse: 18.9 }
        ];

        sortAndRenderData();
        updateSummaryCards();
        updateAlertPanel();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderRankingTable([]);
    }
  }

  // サマリーカードの更新
  function updateSummaryCards() {
    if (currentData.length === 0) return;

    const avgAccuracy = currentData.reduce((sum, item) => sum + item.accuracy, 0) / currentData.length;
    const avgMape = currentData.reduce((sum, item) => sum + item.mape, 0) / currentData.length;
    const avgRmse = currentData.reduce((sum, item) => sum + item.rmse, 0) / currentData.length;
    const alertCount = currentData.filter(item => item.accuracy < 80).length;

    container.querySelector('#avg-accuracy').textContent = avgAccuracy.toFixed(1) + '%';
    container.querySelector('#mape-value').textContent = avgMape.toFixed(1) + '%';
    container.querySelector('#rmse-value').textContent = avgRmse.toFixed(1);
    container.querySelector('#alert-count').textContent = alertCount.toString();
  }

  // アラートパネルの更新
  function updateAlertPanel() {
    const alertItems = currentData.filter(item => item.accuracy < 80);
    const alertList = container.querySelector('#alert-list');

    if (alertItems.length === 0) {
      container.querySelector('#alert-panel').style.display = 'none';
    } else {
      container.querySelector('#alert-panel').style.display = 'block';
      alertList.innerHTML = alertItems.map(item => 
        `<div style="margin-bottom: 8px;">• ${item.storeName} - ${item.category}カテゴリ: 予測精度 ${item.accuracy}% (閾値: 80%)</div>`
      ).join('');
    }
  }

  // ソート機能
  function sortAndRenderData() {
    const sortedData = [...currentData].sort((a, b) => {
      let aVal = a[currentSort.column];
      let bVal = b[currentSort.column];

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (currentSort.direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    renderRankingTable(sortedData);
  }

  // フィルター適用
  function applyFilters() {
    const period = container.querySelector('#filter-period').value;
    const storeId = container.querySelector('#filter-store').value;
    const category = container.querySelector('#filter-category').value;

    let filteredData = [...currentData];

    if (storeId) {
      filteredData = filteredData.filter(item => item.storeId === storeId);
    }

    if (category) {
      filteredData = filteredData.filter(item => item.category === category);
    }

    renderRankingTable(filteredData);

    // サマリーカードも更新
    if (filteredData.length > 0) {
      const avgAccuracy = filteredData.reduce((sum, item) => sum + item.accuracy, 0) / filteredData.length;
      const avgMape = filteredData.reduce((sum, item) => sum + item.mape, 0) / filteredData.length;
      const avgRmse = filteredData.reduce((sum, item) => sum + item.rmse, 0) / filteredData.length;
      const alertCount = filteredData.filter(item => item.accuracy < 80).length;

      container.querySelector('#avg-accuracy').textContent = avgAccuracy.toFixed(1) + '%';
      container.querySelector('#mape-value').textContent = avgMape.toFixed(1) + '%';
      container.querySelector('#rmse-value').textContent = avgRmse.toFixed(1);
      container.querySelector('#alert-count').textContent = alertCount.toString();
    }
  }

  // CSVエクスポート機能
  function exportToCsv() {
    const headers = ['順位', '店舗名', 'カテゴリ', '精度(%)', 'MAPE(%)', 'RMSE'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentData.map((item, index) => [
        index + 1,
        `"${item.storeName}"`,
        `"${item.category}"`,
        item.accuracy,
        item.mape,
        item.rmse
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '予測精度レポート.csv';
    link.click();
  }

  // イベントリスナーの設定
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-export-report').addEventListener('click', exportToCsv);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面に遷移
  });

  // テーブルヘッダーのソート
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('[data-sort]');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      if (currentSort.column === column) {
        currentSort.direction = currentSort.direction === 'asc' ? 'desc' : 'asc';
      } else {
        currentSort.column = column;
        currentSort.direction = 'desc';
      }
      sortAndRenderData();
    }
  });

  // グラフ期間切り替え
  container.addEventListener('click', (e) => {
    if (e.target.id.startsWith('chart-period-')) {
      // ボタンの状態更新
      container.querySelectorAll('[id^="chart-period-"]').forEach(btn => {
        btn.className = 'action-btn secondary';
        btn.style.fontSize = '12px';
        btn.style.padding = '4px 8px';
      });
      e.target.className = 'action-btn';
      e.target.style.fontSize = '12px';
      e.target.style.padding = '4px 8px';

      // グラフ再描画
      drawAccuracyTrendChart();
    }
  });

  // 初期化
  populateStoreFilter();
  loadData();

  // グラフの描画（少し遅延させてcanvasが準備されてから）
  setTimeout(() => {
    drawAccuracyTrendChart();
    drawPredictionVsActualChart();
  }, 100);
}

function(container, apiUrl, tables) {
