    learningRateValue.textContent = parseFloat(learningRateSlider.value).toFixed(4);
  });

  // 全選択チェックボックスの処理
  container.querySelector("#check-all-categories").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll('input[name="category"]');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  container.querySelector("#check-all-datasources").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll('input[name="datasource"]');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // モデル一覧の再描画
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || r.予測結果ID}">
        <td>${r.モデル名 || r.予測モデルバージョン || ""}</td>
        <td>${r.店舗名 || "全店舗"}</td>
        <td>${r.アルゴリズム || "ARIMA"}</td>
        <td>${r.精度目標 || r.予測精度 || "85"}%</td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleString() : ""}</td>
        <td>
          <span style="padding: 3px 8px; border-radius: 3px; font-size: 12px; background: var(--bg-main); color: var(--text);">
            ${r.ステータス || r.予測ステータス || "作成完了"}
