        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  renderRows(tables[0].records || []);

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value;
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderRows(filtered);
    }
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const modelName = container.querySelector("#input-model-name").value.trim();
    if (!modelName) {
      errors.push("モデル名を入力してください");
    }

    const store = container.querySelector("#select-store").value;
    if (!store) {
      errors.push("対象店舗を選択してください");
    }

    const categories = container.querySelectorAll('input[name="category"]:checked');
    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    const datasources = container.querySelectorAll('input[name="datasource"]:checked');
    if (datasources.length === 0) {
      errors.push("データソースを選択してください");
    }

    const learningStart = container.querySelector("#input-learning-start").value;
    const learningEnd = container.querySelector("#input-learning-end").value;

    if (learningStart && learningEnd) {
      const startDate = new Date(learningStart);
      const endDate = new Date(learningEnd);
      const today = new Date();

      if (startDate > today || endDate > today) {
        errors.push("学習期間に未来の日付は設定できません");
      }

      if (startDate > endDate) {
        errors.push("学習期間の開始日は終了日より前の日付を設定してください");
      }
    }

    const accuracyTarget = parseInt(container.querySelector("#input-accuracy-target").value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push("精度目標値は0%から100%の範囲で入力してください");
    }

    return errors;
  }

  // モデル保存
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join("\n"));
      return;
    }

    const modelData = {
      モデル名: container.querySelector("#input-model-name").value.trim(),
      店舗ID: container.querySelector("#select-store").value,
      対象商品カテゴリ: Array.from(container.querySelectorAll('input[name="category"]:checked')).map(cb => cb.value).join(","),
      学習期間開始日: container.querySelector("#input-learning-start").value,
      学習期間終了日: container.querySelector("#input-learning-end").value,
      予測期間: container.querySelector('input[name="prediction-period"]:checked').value,
      使用データソース: Array.from(container.querySelectorAll('input[name="datasource"]:checked')).map(cb => cb.value).join(","),
      アルゴリズム: container.querySelector("#select-algorithm").value,
      学習率: parseFloat(container.querySelector("#slider-learning-rate").value),
      重み付け_売上: parseInt(container.querySelector("#weight-sales").value),
      重み付け_季節: parseInt(container.querySelector("#weight-season").value),
      重み付け_天候: parseInt(container.querySelector("#weight-weather").value),
      重み付け_イベント: parseInt(container.querySelector("#weight-event").value),
      季節性調整パラメータ: parseInt(container.querySelector("#input-seasonality").value),
      精度目標: parseInt(container.querySelector("#input-accuracy-target").value),
      異常値除外設定: container.querySelector("#check-outlier-removal").checked,
      ステータス: "作成完了",
      作成日時: new Date().toISOString(),
      作成者ID: "current-user"
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(0, editingModelId, modelData);
    } else {
      result = await window.aivicApi.save(0, modelData);
    }

    if (result) {
      alert(editingModelId ? "モデルの更新が完了しました" : "モデルの作成が完了しました");

      // フォームリセット
      container.querySelector("#input-model-name").value = "";
      container.querySelector("#select-store").value = "";
      container.querySelectorAll('input[name="category"]').forEach(cb => cb.checked = false);
      container.querySelectorAll('input[name="datasource"]').forEach(cb => cb.checked = false);
      container.querySelector("#check-all-categories").checked = false;
      container.querySelector("#check-all-datasources").checked = false;
      editingModelId = null;
      container.querySelector("#btn-save").textContent = "モデル作成";

      // 一覧更新
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    window.showScreen("scr-1778591780173"); // ダッシュボードに戻る
  });

  // 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このモデルを削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);

      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const model = rows.find(r => (r.id || r.予測結果ID) === id);
        if (model) {
          // フォームに既存データを設定
          container.querySelector("#input-model-name").value = model.モデル名 || model.予測モデルバージョン || "";
          container.querySelector("#select-store").value = model.店舗ID || "";

          if (model.対象商品カテゴリ) {
            const categories = model.対象商品カテゴリ.split(",");
            container.querySelectorAll('input[name="category"]').forEach(cb => {
              cb.checked = categories.includes(cb.value);
            });
          }

          if (model.使用データソース) {
            const datasources = model.使用データソース.split(",");
            container.querySelectorAll('input[name="datasource"]').forEach(cb => {
              cb.checked = datasources.includes(cb.value);
            });
          }

          container.querySelector("#select-algorithm").value = model.アルゴリズム || "ARIMA";
          container.querySelector("#input-accuracy-target").value = model.精度目標 || model.予測精度 || "85";

          editingModelId = id;
          container.querySelector("#btn-save").textContent = "モデル更新";

          // 画面上部にスクロール
          container.scrollIntoView({ behavior: "smooth" });
        }
      }
    }
  });

  // 初期化
  loadStores();
  loadCategories();

  // 今日の日付を学習期間終了日のデフォルトに設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#input-learning-end").value = today;

  // 1年前を学習期間開始日のデフォルトに設定
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  container.querySelector("#input-learning-start").value = oneYearAgo.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
