  const storeAllCheckbox = container.querySelector("#store-all");
  const storeCheckboxes = container.querySelectorAll(".store-checkbox");

  storeAllCheckbox.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // モデル選択時のパラメータ表示
  const modelSelect = container.querySelector("#model-select");
  const parametersDiv = container.querySelector("#model-parameters");

  modelSelect.addEventListener("change", function() {
    const modelParams = {
      "model-v1.0": `
アルゴリズム: Random Forest
特徴量数: 25
学習データ期間: 2022/01/01 - 2023/12/31
ハイパーパラメータ:
  - n_estimators: 100
  - max_depth: 10
  - min_samples_split: 5
      `,
      "model-v1.1": `
アルゴリズム: XGBoost
特徴量数: 30
学習データ期間: 2022/06/01 - 2024/05/31
ハイパーパラメータ:
  - learning_rate: 0.1
  - max_depth: 6
  - n_estimators: 200
      `,
      "model-v2.0": `
アルゴリズム: LSTM Neural Network
特徴量数: 35
学習データ期間: 2023/01/01 - 2024/06/30
ハイパーパラメータ:
  - hidden_units: 128
  - dropout_rate: 0.2
  - learning_rate: 0.001
      `
    };

    parametersDiv.innerHTML = this.value ? 
      `<pre style="color: var(--text); margin: 0;">${modelParams[this.value] || ""}</pre>` :
      '<div class="muted">モデルを選択してください</div>';
  });

  // テスト実行ボタンの処理
  const executeBtn = container.querySelector("#btn-test-execute");
  const testResults = container.querySelector("#test-results");
  const testProgress = container.querySelector("#test-progress");
  const progressBar = container.querySelector("#progress-bar");
  const progressText = container.querySelector("#progress-text");

  executeBtn.addEventListener("click", async function() {
    // バリデーション
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const category = container.querySelector("#category-select").value;
    const selectedStores = Array.from(container.querySelectorAll(".store-checkbox:checked"));
    const selectedDataset = container.querySelector('input[name="dataset"]:checked');

    if (!model) {
      alert("予測モデルが選択されていません");
      return;
    }
    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return;
    }
    if (new Date(endDate) < new Date(startDate)) {
      alert("終了日は開始日より後の日付を設定してください");
      return;
    }
    if (selectedStores.length === 0 && !storeAllCheckbox.checked) {
      alert("店舗が選択されていません");
      return;
    }
    if (!category) {
      alert("商品カテゴリが未選択です");
      return;
    }
    if (!selectedDataset) {
      alert("テストデータセットが選択されていません");
      return;
    }

    // テスト実行開始
    testResults.classList.add("hidden");
    testProgress.classList.remove("hidden");
    executeBtn.disabled = true;

    // プログレスバーのアニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 95) progress = 95;
      progressBar.style.width = progress + "%";
      progressText.textContent = Math.floor(progress) + "%";
    }, 500);

    // 模擬テスト実行（実際の処理時間をシミュレート）
    await new Promise(resolve => setTimeout(resolve, 3000));

    // プログレス完了
    clearInterval(progressInterval);
    progressBar.style.width = "100%";
    progressText.textContent = "100%";

    await new Promise(resolve => setTimeout(resolve, 500));

    // 結果表示
    testProgress.classList.add("hidden");
    testResults.classList.remove("hidden");
    executeBtn.disabled = false;

    // 模擬結果データ
    const mapeValue = (Math.random() * 15 + 5).toFixed(2);
    const rmseValue = (Math.random() * 50 + 20).toFixed(2);
    const r2Value = (Math.random() * 0.3 + 0.7).toFixed(3);
    const executionTime = (Math.random() * 120 + 30).toFixed(0);

    container.querySelector("#mape-value").textContent = mapeValue + "%";
    container.querySelector("#rmse-value").textContent = rmseValue;
    container.querySelector("#r2-value").textContent = r2Value;
    container.querySelector("#execution-time").textContent = executionTime + "秒";

    // グラフ描画
    drawComparisonChart();

    // テスト履歴に追加
    const historyData = {
      実行日時: new Date().toLocaleString("ja-JP"),
      モデル名: model,
      テスト期間: `${startDate} - ${endDate}`,
      対象店舗数: storeAllCheckbox.checked ? "全店舗" : selectedStores.length,
      MAPE: mapeValue + "%",
      RMSE: rmseValue,
      実行時間: executionTime + "秒"
    };

    const saved = await window.aivicApi.save(0, historyData);
    if (saved) {
      const rows = await window.aivicApi.list(0);
      if (rows) renderHistoryRows(rows);
    }
  });

  // グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 模擬データ生成
    const days = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.2) * 20;
      actualData.push(base + (Math.random() - 0.5) * 30);
      predictedData.push(base + (Math.random() - 0.5) * 20);
    }

    // グラフ描画エリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ描画
    const maxValue = Math.max(...actualData, ...predictedData);
    const minValue = Math.min(...actualData, ...predictedData);
    const valueRange = maxValue - minValue;

    // 実績値線
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < days; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線
    ctx.strokeStyle = '#ff6a4a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < days; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '14px sans-serif';
    ctx.fillText('実績値', padding + 20, padding - 20);
    ctx.fillStyle = '#4a9eff';
    ctx.fillRect(padding, padding - 30, 15, 3);

    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('予測値', padding + 120, padding - 20);
    ctx.fillStyle = '#ff6a4a';
    ctx.fillRect(padding + 100, padding - 30, 15, 3);
  }

  // エクスポートボタンの処理
  const exportBtn = container.querySelector("#btn-export-results");
  exportBtn.addEventListener("click", function() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const mape = container.querySelector("#mape-value").textContent;
    const rmse = container.querySelector("#rmse-value").textContent;
    const r2 = container.querySelector("#r2-value").textContent;
    const execTime = container.querySelector("#execution-time").textContent;

    const csvContent = [
      '\uFEFF', // BOM
      'テスト実行結果レポート\n',
      `実行日時,${new Date().toLocaleString("ja-JP")}\n`,
      `モデル名,${model}\n`,
      `テスト期間,${startDate} - ${endDate}\n`,
      `MAPE,${mape}\n`,
      `RMSE,${rmse}\n`,
      `決定係数(R²),${r2}\n`,
      `実行時間,${execTime}\n`
    ].join('');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 履歴テーブルのイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderHistoryRows(rows);
      return;
    }

    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      alert("詳細表示機能は開発中です");
      return;
    }
  });

  // 最新データの読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderHistoryRows(rows);
  });
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let isProcessing = false;
  let currentAppliedModel = null;

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#input-start-datetime').value = now.toISOString().slice(0, 16);

  // モデル一覧を読み込み
  async function loadModels() {
    try {
      const models = await window.aivicApi.list(12); // 需要予測結果テーブルからモデル情報を取得
      if (models) {
        const uniqueModels = [];
        const modelVersions = new Set();

        models.forEach(result => {
          const key = result.予測モデルバージョン;
          if (key && !modelVersions.has(key)) {
            modelVersions.add(key);
            uniqueModels.push({
              id: key,
              name: `AI需要予測モデル ${key}`,
              version: key,
              accuracy: result.予測精度 || 85,
              status: Math.random() > 0.3 ? '検証完了' : '検証中'
            });
          }
        });

        currentModels = uniqueModels;
        renderModelOptions();
      }
    } catch (error) {
      console.error('モデル読み込みエラー:', error);
    }
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        currentStores = stores.filter(store => store.有効フラグ);
        renderStoreList();
      }
    } catch (error) {
      console.error('店舗読み込みエラー:', error);
    }
  }

  // モデル選択肢を描画
  function renderModelOptions() {
    const select = container.querySelector('#select-model');
    select.innerHTML = '<option value="">-- モデルを選択してください --</option>';

    currentModels.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (v${model.version}) - 精度:${model.accuracy}%`;
      option.dataset.status = model.status;
      select.appendChild(option);
    });
  }

  // 店舗一覧を描画
  function renderStoreList() {
    const storeList = container.querySelector('#store-list');
    storeList.innerHTML = currentStores.map(store => `
      <label style="display: flex; align-items: center; gap: 8px; color: var(--text); cursor: pointer; margin-bottom: 8px;">
        <input type="checkbox" class="store-checkbox" value="${store.店舗ID}" style="margin: 0;">
        <span>${store.店舗名} (${store.店舗コード})</span>
      </label>
    `).join('');

    updateSelectedCount();
  }

  // 選択店舗数を更新
  function updateSelectedCount() {
    const checkboxes = container.querySelectorAll('.store-checkbox:checked');
    const count = checkboxes.length;
    container.querySelector('#selected-count').textContent = count;

    // 影響範囲を更新
    if (count > 0) {
      updateImpactAnalysis(count);
    }
  }

  // 影響範囲分析を更新
  function updateImpactAnalysis(storeCount) {
    const impactSection = container.querySelector('#impact-analysis');
    impactSection.classList.remove('hidden');

    container.querySelector('#impact-stores').textContent = storeCount;
    container.querySelector('#impact-products').textContent = storeCount * 150; // 店舗あたり平均150商品と仮定
    container.querySelector('#impact-time').textContent = Math.ceil(storeCount * 2.5); // 店舗あたり2.5分と仮定
  }

  // モデル詳細を表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    if (model) {
      const detailsSection = container.querySelector('#model-details');
      detailsSection.classList.remove('hidden');

      container.querySelector('#detail-name').textContent = model.name;
      container.querySelector('#detail-version').textContent = model.version;
      container.querySelector('#detail-accuracy').textContent = `${model.accuracy}%`;
      container.querySelector('#detail-status').textContent = model.status;

      // ロールバックボタンの状態を更新
      const rollbackBtn = container.querySelector('#btn-rollback');
      rollbackBtn.disabled = !currentAppliedModel;
    } else {
      container.querySelector('#model-details').classList.add('hidden');
    }
  }

  // 適用前検証を実行
  async function runValidation() {
    const modelId = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked'));

    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return;
    }

    if (selectedStores.length === 0) {
      alert('適用対象の店舗が選択されていません');
      return;
    }

    const model = currentModels.find(m => m.id === modelId);
    if (model.status !== '検証完了') {
      alert('検証が完了していないモデルは本番適用できません');
      return;
    }

    const validationSection = container.querySelector('#validation-results');
    validationSection.classList.remove('hidden');

    const content = container.querySelector('#validation-content');
    content.innerHTML = `
      <div style="color: var(--text);">
        <div style="margin-bottom: 10px;">✓ モデル整合性チェック: 正常</div>
        <div style="margin-bottom: 10px;">✓ 店舗データ整合性: 正常</div>
        <div style="margin-bottom: 10px;">✓ システムリソース: 十分</div>
        <div style="margin-bottom: 10px;">✓ バックアップ領域: 十分</div>
        <div style="color: var(--primary); font-weight: bold;">検証結果: 適用可能</div>
      </div>
    `;

    container.querySelector('#btn-apply').disabled = false;
  }

  // モデル適用を実行
  async function applyModel() {
    const modelId = container.querySelector('#select-model').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked'));
    const startDateTime = container.querySelector('#input-start-datetime').value;
    const retentionDays = parseInt(container.querySelector('#input-retention-days').value);
    const backupEnabled = container.querySelector('#backup-enabled').checked;

    // バリデーション
    if (!modelId) {
      alert('適用対象のモデルが選択されていません');
      return;
    }

    if (selectedStores.length === 0) {
      alert('適用対象の店舗が選択されていません');
      return;
    }

    if (!startDateTime) {
      alert('適用開始日時を設定してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      alert('適用開始日時は現在日時以降を指定してください');
      return;
    }

    if (retentionDays <= 0) {
      alert('現行モデル保持期間は1日以上を設定してください');
      return;
    }

    if (isProcessing) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return;
    }

    if (!confirm(`${selectedStores.length}店舗にモデル「${modelId}」を適用します。よろしいですか？`)) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-apply').disabled = true;
    container.querySelector('#btn-validate').disabled = true;

    // 進捗表示開始
    const progressSection = container.querySelector('#progress-section');
    progressSection.classList.remove('hidden');

    const resultSection = container.querySelector('#result-log');
    resultSection.classList.remove('hidden');

    const logContent = container.querySelector('#log-content');
    logContent.textContent = '';

    // 適用処理をシミュレート
    const steps = [
      { text: 'バックアップ作成中...', progress: 10 },
      { text: '現行モデル停止中...', progress: 25 },
      { text: '新モデル配置中...', progress: 50 },
      { text: '店舗別設定適用中...', progress: 75 },
      { text: 'サービス再開中...', progress: 90 },
      { text: '適用完了', progress: 100 }
    ];

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];

      // 進捗更新
      container.querySelector('#progress-bar').style.width = `${step.progress}%`;
      container.querySelector('#progress-text').textContent = step.text;
      container.querySelector('#progress-percent').textContent = `${step.progress}%`;

      // ログ追加
      const timestamp = new Date().toLocaleTimeString();
      logContent.textContent += `[${timestamp}] ${step.text}\n`;
      logContent.scrollTop = logContent.scrollHeight;

      // 待機
      await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 1000));
    }

    // 適用完了処理
    currentAppliedModel = modelId;
    container.querySelector('#btn-rollback').disabled = false;
    isProcessing = false;

    alert('モデルの本番適用が完了しました');
  }

  // ロールバック実行
  async function rollbackModel() {
    if (!currentAppliedModel) {
      alert('ロールバック対象のモデルが存在しません');
      return;
    }

    if (isProcessing) {
      alert('処理実行中のため、ロールバックできません');
      return;
    }

    if (!confirm('モデルをロールバックします。よろしいですか？')) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-rollback').disabled = true;

    // ロールバック処理をシミュレート
    const progressSection = container.querySelector('#progress-section');
    progressSection.classList.remove('hidden');

    const logContent = container.querySelector('#log-content');
    logContent.textContent = '';

    const steps = [
      { text: 'ロールバック開始...', progress: 20 },
      { text: '前バージョン復元中...', progress: 60 },
      { text: 'サービス再開中...', progress: 90 },
      { text: 'ロールバック完了', progress: 100 }
    ];

    for (const step of steps) {
      container.querySelector('#progress-bar').style.width = `${step.progress}%`;
      container.querySelector('#progress-text').textContent = step.text;
      container.querySelector('#progress-percent').textContent = `${step.progress}%`;

      const timestamp = new Date().toLocaleTimeString();
      logContent.textContent += `[${timestamp}] ${step.text}\n`;
      logContent.scrollTop = logContent.scrollHeight;

      await new Promise(resolve => setTimeout(resolve, 800));
    }

    currentAppliedModel = null;
    isProcessing = false;
    container.querySelector('#btn-apply').disabled = false;
    container.querySelector('#btn-validate').disabled = false;

    alert('ロールバックが完了しました');
  }

  // イベントリスナー設定
  container.querySelector('#select-model').addEventListener('change', (e) => {
    const modelId = e.target.value;
    if (modelId) {
      showModelDetails(modelId);
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      container.querySelector('#btn-apply').disabled = true;
    }
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSelectedCount();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateSelectedCount();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.store-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.store-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all-stores');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
      } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
      }
    }
  });

  container.querySelector('#input-retention-days').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value === 0) {
      alert('保持期間に0日が設定されています。1日以上を設定してください。');
      e.target.focus();
    }
  });

  container.querySelector('#btn-validate').addEventListener('click', runValidation);
  container.querySelector('#btn-apply').addEventListener('click', applyModel);
  container.querySelector('#btn-rollback').addEventListener('click', rollbackModel);

  // 初期データ読み込み
  loadModels();
  loadStores();
}
